  'Integrated Marketing Communications',
  'Integrated Marketing Communications teaches students how to design coordinated, measurable, and ethically responsible campaigns across advertising, public relations, digital, social, direct, experiential, sponsorship, retail, and owned media. Students learn to move from business problem to customer insight, positioning, creative brief, media plan, budget, execution workflow, and performance dashboard. The course is built around professional campaign practice: every communication choice must have a strategic reason, a defined audience, a clear message role, and a measurable learning plan.',
  $imcjson${"slug": "integrated-marketing-communications", "title": "Integrated Marketing Communications", "description": "Integrated Marketing Communications teaches students how to design coordinated, measurable, and ethically responsible campaigns across advertising, public relations, digital, social, direct, experiential, sponsorship, retail, and owned media. Students learn to move from business problem to customer insight, positioning, creative brief, media plan, budget, execution workflow, and performance dashboard. The course is built around professional campaign practice: every communication choice must have a strategic reason, a defined audience, a clear message role, and a measurable learning plan.", "topics": [{"id": "731f90e1-bbee-499e-b837-8d8c235f21a3", "type": "topic", "title": "IMC Strategy and Campaign Architecture", "description": "This opening unit frames IMC as a disciplined system for aligning brand, audience, message, channel, and measurement. Students learn to turn business goals into coordinated communication choices rather than isolated tactics.", "children": [{"id": "def39c07-c172-4e12-95aa-85a72a58b347", "type": "subtopic", "title": "Strategic Role of IMC", "children": [{"id": "c9ad6f37-20b5-45a9-bccb-a8a311f19e2b", "type": "concept", "title": "Business goals, communication goals, and behavioral objectives"}, {"id": "21d88f55-9695-4f2d-bd5d-296864bd20b0", "type": "concept", "title": "Brand consistency across paid, owned, earned, shared, and retail channels"}, {"id": "2c53d32a-be8c-48be-a92a-98598f911935", "type": "concept", "title": "Integration across advertising, PR, direct, sales, social, content, and events"}], "description": "The goal is to understand why integrated communications matter: they reduce message fragmentation and make every customer touchpoint reinforce a coherent market position."}, {"id": "4cfd7709-a9b6-459b-badd-eb7beec2feb8", "type": "subtopic", "title": "Campaign Planning Models", "children": [{"id": "4ec84146-2003-4b40-9975-330bfd80e9a2", "type": "concept", "title": "Situation analysis, audience insight, objectives, strategy, tactics, action, control"}, {"id": "ce156cfa-942f-44f1-b5e6-2367819d0e92", "type": "concept", "title": "Brief-to-execution workflow and approval gates"}, {"id": "e5ec1b60-52c8-4f4d-9825-88f419965658", "type": "concept", "title": "Campaign maps that connect message, channel, timing, and measurement"}], "description": "Students learn practical planning models that convert ambiguity into an organized campaign logic."}, {"id": "31e88dce-5569-4b57-81f3-2f25ead47497", "type": "subtopic", "title": "Professional IMC Standards", "children": [{"id": "adec8e0e-0208-4b06-88aa-16d639461c70", "type": "concept", "title": "Evidence-based strategy rather than channel-first execution"}, {"id": "ce379ae1-09ec-4df1-9cfa-a1e988ba471d", "type": "concept", "title": "Cross-functional collaboration among brand, media, analytics, product, and sales"}, {"id": "9440eb71-ade1-499b-9d24-7e2822a9c3af", "type": "concept", "title": "Portfolio thinking across short-term activation and long-term brand building"}], "description": "This subtopic sets the bar for professional campaign thinking in top marketing programs and agencies."}]}, {"id": "802fa105-53c0-4c5c-b6c7-80afd68df0df", "type": "topic", "title": "Customer Insight, Segmentation, Targeting and Positioning", "description": "IMC becomes powerful when it is grounded in a precise view of customers and the market. This section develops the insight work behind who the campaign serves and what distinctive meaning it should own.", "children": [{"id": "d62b5a6e-ee50-412d-9048-1da1b6477010", "type": "subtopic", "title": "Customer and Market Insight", "children": [{"id": "102533dd-6747-4df9-9450-a45822d88d85", "type": "concept", "title": "Jobs-to-be-done, motivations, barriers, and triggers"}, {"id": "aca564c9-23ab-4c96-9cac-3b3c8ddad22c", "type": "concept", "title": "Category entry points and moments of need"}, {"id": "9acb4552-4a25-4128-9220-1f94665201f4", "type": "concept", "title": "Voice-of-customer, social listening, search behavior, and review mining"}], "description": "Students learn to move from demographic description to sharper human, behavioral, cultural, and category insight."}, {"id": "3396ce21-73c0-40b6-9d79-365a64461efe", "type": "subtopic", "title": "Segmentation and Targeting", "children": [{"id": "10d4346a-f9e3-4bad-890b-b550e14f7a4f", "type": "concept", "title": "Behavioral, psychographic, firmographic, and value-based segmentation"}, {"id": "515ff48a-23e6-4184-bd53-410009f6e04e", "type": "concept", "title": "Target attractiveness, accessibility, and strategic fit"}, {"id": "c002b902-fb0a-4d2a-8d14-b1b119668993", "type": "concept", "title": "Primary, secondary, influencer, and internal stakeholder audiences"}], "description": "The purpose is to choose valuable audiences deliberately instead of trying to speak to everyone at once."}, {"id": "d9cc0c33-3995-4522-8188-eafa2cb46809", "type": "subtopic", "title": "Positioning and Value Proposition", "children": [{"id": "41a63e76-e3e9-4266-b915-24f1bebc94df", "type": "concept", "title": "Points of parity and points of difference"}, {"id": "3ecc864b-cdd3-4acb-bcac-e0f2672f5821", "type": "concept", "title": "Positioning statements and value propositions"}, {"id": "60c79ef9-fe2b-445c-bab7-2bf7547b0f3a", "type": "concept", "title": "Competitor mapping, perceptual maps, and white-space analysis"}], "description": "Students learn how a campaign should sharpen what the brand means and why that meaning matters."}]}, {"id": "689bcfc4-f770-4e67-a350-14ee942af06b", "type": "topic", "title": "Brand Identity, Equity and Message Consistency", "description": "Integrated communications must protect and grow brand equity. This unit connects visual identity, verbal identity, positioning, memory structures, and trust.", "children": [{"id": "fb824f76-c470-42d2-b7d4-430ae1a4defa", "type": "subtopic", "title": "Brand Identity Systems", "children": [{"id": "c2eb4989-1aeb-455c-ab41-f1ceb3fbdb09", "type": "concept", "title": "Name, logo, color, typography, voice, tone, and sonic cues"}, {"id": "a6b4338c-1fab-4462-ac31-92beae42f7cb", "type": "concept", "title": "Brand guidelines, governance, and approval systems"}, {"id": "a1c50d8a-e44f-48d7-954c-bee8834b480f", "type": "concept", "title": "Adaptation across formats without losing coherence"}], "description": "Students learn the elements that make a brand recognizable and usable across every channel."}, {"id": "ec895059-cf8e-425d-92b5-c5388f0eeeb1", "type": "subtopic", "title": "Brand Equity and Mental Availability", "children": [{"id": "8fc4f80d-5b36-443c-b43b-babdbdb4ea70", "type": "concept", "title": "Awareness, associations, perceived quality, loyalty, and differentiation"}, {"id": "4676de5a-e391-48a2-b96a-809f0259b0cf", "type": "concept", "title": "Distinctive brand assets and category cues"}, {"id": "d5254ab8-ebab-45f9-a48e-cdc60daf1893", "type": "concept", "title": "Long-term brand building versus short-term conversion"}], "description": "The gist is that communication builds memory, salience, associations, and preference over time."}, {"id": "84d06fdc-012b-4b90-af32-7c0c12bd8649", "type": "subtopic", "title": "Message Consistency and Variation", "children": [{"id": "31da60d4-8123-48c8-b2ec-584d19e36842", "type": "concept", "title": "Message hierarchy and proof architecture"}, {"id": "d5519d12-3bb5-4a47-b7e2-65337e6a247f", "type": "concept", "title": "Core claims, reasons to believe, and supporting evidence"}, {"id": "d032c4db-5d22-4cbe-ae81-caa3555d48cc", "type": "concept", "title": "Audience, channel, and funnel adaptations"}], "description": "Students learn to distinguish strategic consistency from repetitive sameness."}]}, {"id": "cc00ca58-4faf-42ab-9bb3-14149ba2693b", "type": "topic", "title": "The Creative Brief and Big Idea", "description": "A strong brief is the bridge between strategy and creative work. This section teaches students how to express the problem, audience, promise, evidence, tone, and constraints in a way that unlocks great execution.", "children": [{"id": "d2a71148-e94b-433f-b08d-1f0d46428302", "type": "subtopic", "title": "Creative Brief Foundations", "children": [{"id": "eb07fc70-bc5d-4645-ba45-de03d44ff3ae", "type": "concept", "title": "Problem statement, objective, audience, insight, proposition, support, tone, mandatories"}, {"id": "baea307b-72ad-41f6-a501-b51c803b68cf", "type": "concept", "title": "Single-minded message and creative tension"}, {"id": "266c3d24-651a-4c18-9304-1c2cefd7cdd2", "type": "concept", "title": "Evaluation criteria for whether the idea answers the brief"}], "description": "Students learn what a brief must contain and why vague briefs lead to weak campaigns."}, {"id": "089d6e6b-0afe-4dfe-ad10-8a2b232bf10f", "type": "subtopic", "title": "The Big Idea", "children": [{"id": "ffb49a27-d7fd-4936-97c3-95adb9104646", "type": "concept", "title": "Central campaign thought and strategic hook"}, {"id": "58b4cba5-eda9-45d6-b8d2-68a756390f99", "type": "concept", "title": "Concept testing and stress-testing across channels"}, {"id": "460bd16b-0d70-4e8f-aa8c-fc7d80eb55e0", "type": "concept", "title": "Distinctiveness, emotional resonance, usefulness, and shareability"}], "description": "This subtopic focuses on campaign concepts that travel across media while staying memorable."}, {"id": "bcad289d-b976-456b-b581-4515468e59b4", "type": "subtopic", "title": "Creative Review and Feedback", "children": [{"id": "768eddbc-3352-4f1e-8f5c-c74b2490eb32", "type": "concept", "title": "Feedback language for message, brand fit, clarity, originality, and feasibility"}, {"id": "206bdaec-9b11-4191-860d-48f820754792", "type": "concept", "title": "Iteration cycles from thumbnails to scripts to prototypes"}, {"id": "dbc2b80a-057c-4010-a094-2f0348266920", "type": "concept", "title": "Avoiding committee dilution and preserving strategic intent"}], "description": "Students learn how to critique creative work against strategy instead of personal taste."}]}, {"id": "ef25ff45-e634-45b2-bc32-856cdee07d97", "type": "topic", "title": "Advertising Strategy and Persuasive Communication", "description": "Advertising remains a central IMC tool because it can shape awareness, memory, emotion, and demand at scale. This unit connects persuasion theory with practical campaign design.", "children": [{"id": "ad199b64-9fd4-4ea6-828e-3b8d668d9400", "type": "subtopic", "title": "Persuasion and Message Strategy", "children": [{"id": "2d53577a-d795-4309-b1e5-2bf8ee19f524", "type": "concept", "title": "Ethos, pathos, logos, social proof, scarcity, authority, and reciprocity"}, {"id": "1cbfaf39-3bb0-4483-9cef-a68f606f1014", "type": "concept", "title": "Elaboration likelihood, framing, priming, and fluency"}, {"id": "1f2c8d9e-8f93-4551-b9f4-98311c89ddf2", "type": "concept", "title": "Rational, emotional, transformational, comparative, and reminder appeals"}], "description": "Students learn how communication influences attention, comprehension, attitude, intention, and action."}, {"id": "242d1dd6-9c12-4a66-877b-304890186a2d", "type": "subtopic", "title": "Advertising Objectives", "children": [{"id": "b12cc067-6778-4b7c-a7e4-75d703f5eadd", "type": "concept", "title": "Awareness, consideration, preference, trial, repeat purchase, loyalty, and advocacy"}, {"id": "25ade7ec-0379-4c51-a339-e9c4fbe1b164", "type": "concept", "title": "Category creation, repositioning, launch, defense, and growth objectives"}, {"id": "b9758ce2-a451-4ea9-b4c9-7b9777bd8c04", "type": "concept", "title": "Behavioral outcomes versus communication outcomes"}], "description": "The point is to choose the right advertising job before choosing the advertisement."}, {"id": "af33520a-414a-4aa6-b5c3-9382c4dc49e3", "type": "subtopic", "title": "Executional Formats", "children": [{"id": "b98d88a0-0d97-4df9-92f0-3ffdc373655c", "type": "concept", "title": "Demonstration, testimonial, slice-of-life, problem-solution, story, humor, and comparison"}, {"id": "050b20f9-a1bb-433c-a3f9-bfc086f2d722", "type": "concept", "title": "Copy platforms, scripts, storyboards, and key visuals"}, {"id": "6ad2382b-97e6-4bd1-ae85-553f5144f64e", "type": "concept", "title": "Claims support, substantiation, and responsible persuasion"}], "description": "Students learn the craft options that turn strategy into attention-worthy communication."}]}, {"id": "925c3b4b-e3e9-4b9f-8d13-a951786a0a78", "type": "topic", "title": "Creative Development, Copywriting and Art Direction", "description": "Creative execution determines whether strategy becomes vivid enough for people to notice, understand, and remember. This section trains the craft layer of IMC.", "children": [{"id": "560ef1a5-114d-44ae-a075-d536cdead579", "type": "subtopic", "title": "Copywriting for Campaigns", "children": [{"id": "ea45f5d0-e764-40b1-a901-76c4d5160af9", "type": "concept", "title": "Headlines, taglines, body copy, captions, scripts, subject lines, and CTAs"}, {"id": "12cc6a13-9f52-42c3-873a-2e4dab156bd5", "type": "concept", "title": "Clarity, brevity, specificity, rhythm, and tone"}, {"id": "d0ceaa56-96e3-4bbb-9c3f-1c83c3613578", "type": "concept", "title": "Writing for different funnel stages and formats"}], "description": "Students learn how words move from headline to call-to-action while carrying the brand's voice."}, {"id": "cde562e4-2588-4a37-8024-36b30719dcc5", "type": "subtopic", "title": "Art Direction and Visual Storytelling", "children": [{"id": "830f3fba-cd8e-4b28-9f0c-8fab4e040db4", "type": "concept", "title": "Composition, hierarchy, color, imagery, typography, and motion cues"}, {"id": "4de1cac7-ec29-4c2c-8bc5-4f36b6af263c", "type": "concept", "title": "Brand asset use across print, digital, video, and outdoor"}, {"id": "2169bff3-8ef3-4566-9c53-bfa0f9af7fda", "type": "concept", "title": "Accessibility, legibility, and mobile-first visual design"}], "description": "The aim is to understand how design choices communicate before the audience reads a word."}, {"id": "c9be6bac-7b00-4db7-a14f-5f51e5f6af68", "type": "subtopic", "title": "Production and Adaptation", "children": [{"id": "76bf164a-8654-4c34-9537-3f98da0b1433", "type": "concept", "title": "Asset matrices, deliverable lists, localization, and resizing"}, {"id": "12331290-9290-4881-8eca-57cf1302d6b2", "type": "concept", "title": "Photography, video, motion, audio, and design production basics"}, {"id": "e550b009-d318-49cb-b603-1e500844fc02", "type": "concept", "title": "Versioning for audiences, platforms, placements, and tests"}], "description": "Students learn to manage creative work across formats, deadlines, budgets, and technical specs."}]}, {"id": "ad69ecc2-ded8-4396-85a7-a99e512e879d", "type": "topic", "title": "Media Planning, Buying and Channel Mix", "description": "A great message fails if it reaches the wrong people in the wrong context. This unit teaches how media choices translate objectives into reach, frequency, impact, and efficiency.", "children": [{"id": "29bdcf22-8d34-44e3-bb4a-322d1848dad8", "type": "subtopic", "title": "Media Objectives and Metrics", "children": [{"id": "4f894d74-53b3-4103-afaf-b9a76111e62a", "type": "concept", "title": "Reach, frequency, GRPs, impressions, CPM, CPC, CPA, viewability, and completion rate"}, {"id": "b3055f04-0984-4942-93a5-0068a1edab02", "type": "concept", "title": "Audience quality, context, timing, and duplication"}, {"id": "f12e98f2-d430-4e2f-8fdb-780f5f93f963", "type": "concept", "title": "Effective frequency and diminishing returns"}], "description": "Students learn the language of media planning so they can connect exposure to outcomes."}, {"id": "d09893b9-9647-4abe-993a-32fdb55e5884", "type": "subtopic", "title": "Channel Mix Strategy", "children": [{"id": "b06b7101-a651-4ac2-b927-be7b0fa9c765", "type": "concept", "title": "Television, streaming, audio, print, out-of-home, search, social, display, email, influencer, PR, events"}, {"id": "b0fa4255-cb49-43c0-b222-cae3b59740db", "type": "concept", "title": "Funnel role and customer journey fit by channel"}, {"id": "a735c3aa-540f-41ff-8a62-8ef9f8c7d177", "type": "concept", "title": "Integrated flighting, pulsing, sequencing, and always-on media"}], "description": "This subtopic explains how paid, owned, earned, shared, retail, and partner channels work together."}, {"id": "eaf3f422-9b2d-455e-b2fc-141f7e94b239", "type": "subtopic", "title": "Buying and Optimization", "children": [{"id": "d47bfa5b-d0e1-4640-9631-d131ad7f97b0", "type": "concept", "title": "Briefing media partners and evaluating proposals"}, {"id": "d39bfab4-78d7-4456-bea5-d765bc3674a6", "type": "concept", "title": "Programmatic, direct buys, sponsorships, and marketplace dynamics"}, {"id": "2940c0f0-f3d4-4061-8c78-69c43ffd2c44", "type": "concept", "title": "Budget pacing, bid strategy, creative rotation, and optimization rules"}], "description": "Students learn the operational side of turning plans into real placements and learning cycles."}]}, {"id": "0b2d0b81-ed05-4d58-9e01-3ba43ee5d4d6", "type": "topic", "title": "Digital, Social and Content IMC", "description": "Digital channels make integration more complex because messages can be targeted, personalized, measured, shared, and remixed. This section builds a modern platform-aware communication toolkit.", "children": [{"id": "9ee3d53e-ea53-4040-aef3-ad7ae3db502c", "type": "subtopic", "title": "Platform Strategy", "children": [{"id": "88be2973-b448-48ae-aab5-c65b0757512b", "type": "concept", "title": "Search, social, video, display, retail media, messaging, communities, and creators"}, {"id": "79fe921d-da5a-4193-9a71-52cfab83f0c9", "type": "concept", "title": "Platform-native formats, algorithms, and attention patterns"}, {"id": "93a11944-069a-4335-9be4-7f15e0cb74f6", "type": "concept", "title": "Organic, paid, and boosted distribution"}], "description": "Students learn that each platform has its own audience behavior, creative grammar, and measurement limits."}, {"id": "af8ae819-40c6-4e59-9ef7-ea054a5f15d6", "type": "subtopic", "title": "Content Systems", "children": [{"id": "8df33451-11d8-442d-b7db-797aada6c162", "type": "concept", "title": "Content pillars, editorial calendars, atomization, and repurposing"}, {"id": "a6a60eba-1a9d-4884-b676-6213592a3d65", "type": "concept", "title": "Hero, hub, help, and always-on content models"}, {"id": "67ae9286-e15e-470c-ba75-c440374f4e04", "type": "concept", "title": "SEO, social search, discoverability, and content governance"}], "description": "The point is to manage content as a strategic system rather than a calendar of disconnected posts."}, {"id": "6b76f004-aa67-431d-bd81-c71fb9468210", "type": "subtopic", "title": "Social Engagement and Community", "children": [{"id": "25b74eb6-b45f-419d-afb6-ad731a482e78", "type": "concept", "title": "Community management, response protocols, and moderation"}, {"id": "1efeca61-0d45-414e-b30f-7fef5ba13377", "type": "concept", "title": "User-generated content, advocacy, and social proof"}, {"id": "b8597550-0a5b-45ae-ba03-a0bc7682d2e3", "type": "concept", "title": "Listening, sentiment, cultural timing, and escalation"}], "description": "Students learn how IMC changes when audiences can respond, organize, critique, and co-create."}]}, {"id": "1abff898-2e4a-4795-97f3-b9f8ed037c73", "type": "topic", "title": "Public Relations, Reputation and Issues Management", "description": "PR connects campaigns to credibility, stakeholders, and the public conversation. This unit teaches how earned influence and reputation work alongside paid and owned media.", "children": [{"id": "f41e1e38-57cb-4eb1-965a-4376838f3384", "type": "subtopic", "title": "PR Strategy and Media Relations", "children": [{"id": "0d54e47f-76e4-4d80-8a56-908cb1703f72", "type": "concept", "title": "Press releases, pitches, media lists, briefings, and embargoes"}, {"id": "843f4d56-8d0d-4e59-8a05-ffe3f97de8e5", "type": "concept", "title": "News values, spokesperson preparation, and message discipline"}, {"id": "d7a05ff2-2d49-4efb-9373-170d54151684", "type": "concept", "title": "Earned media integration with paid and owned assets"}], "description": "Students learn how to earn attention through news value, relevance, and relationship building."}, {"id": "ba41671d-343d-4631-9454-5fb33044b93a", "type": "subtopic", "title": "Stakeholder Communication", "children": [{"id": "1874a55e-f10a-4939-89ad-3beb7a26ddf5", "type": "concept", "title": "Employees, investors, regulators, communities, partners, and advocacy groups"}, {"id": "c8ffd24c-1b21-45fd-97b3-62ceda50169b", "type": "concept", "title": "Internal alignment and executive communication"}, {"id": "87cbf7b4-322f-4ef6-a10e-2a4ddfd44717", "type": "concept", "title": "Corporate social responsibility and social impact claims"}], "description": "The focus is on audiences beyond customers who shape brand legitimacy and risk."}, {"id": "82dc67cb-c482-43c1-a41e-4fcf8f8a3701", "type": "subtopic", "title": "Issues and Crisis Response", "children": [{"id": "d8fafe19-1e4a-404c-bd27-382beaacfd6e", "type": "concept", "title": "Risk mapping, scenarios, holding statements, and escalation trees"}, {"id": "a7a76a1f-b530-40c3-bc4c-6b084ded1408", "type": "concept", "title": "Apology, correction, transparency, and accountability"}, {"id": "3cb83dd0-0a19-4375-977c-c148612409b7", "type": "concept", "title": "Monitoring, misinformation, and post-crisis learning"}], "description": "Students learn how to communicate when trust, safety, or reputation is under pressure."}]}, {"id": "588d0ec2-ea13-4eb3-b2f0-6ede27bec0ab", "type": "topic", "title": "Sales Promotion, Retail and Shopper Marketing", "description": "Promotions can stimulate action quickly, but they must be designed carefully so they do not erode brand equity or margins. This section connects shopper psychology with activation discipline.", "children": [{"id": "9c86af2a-2ace-42d8-afc8-d147ba6ab41b", "type": "subtopic", "title": "Promotion Objectives", "children": [{"id": "01158f93-cd76-48d2-965c-334e91ce6c1f", "type": "concept", "title": "Trial, repeat, stock-up, switching, traffic, basket size, and loyalty"}, {"id": "571f8d7b-adfb-4804-932e-cb8f68c4431e", "type": "concept", "title": "Consumer promotions, trade promotions, and channel incentives"}, {"id": "2dfc6e11-cfa2-44ef-a760-27fc41065364", "type": "concept", "title": "Promo calendars, seasonality, and campaign integration"}], "description": "Students learn when promotions are appropriate and what business problem they should solve."}, {"id": "8bc2de7e-ecf5-4c57-bdce-c602437c4c40", "type": "subtopic", "title": "Offer Design and Behavioral Triggers", "children": [{"id": "df2f18f0-e3fc-4e29-a399-d71d71060c89", "type": "concept", "title": "Coupons, rebates, bundles, samples, contests, sweepstakes, and loyalty rewards"}, {"id": "b24d23d4-51e8-4121-bd94-89e5319c4c90", "type": "concept", "title": "Urgency, scarcity, thresholds, framing, and reference price effects"}, {"id": "c9dccf82-909e-4b40-a24c-b7bb0c934ea3", "type": "concept", "title": "Legal, ethical, and fairness considerations"}], "description": "The gist is that promotion mechanics shape perceived value and action."}, {"id": "8b1afa6b-1956-446d-992a-93fb73e00bd0", "type": "subtopic", "title": "Retail and Shopper Communication", "children": [{"id": "faf30aaa-9a3a-479e-9b22-6fce5bf80911", "type": "concept", "title": "Shelf, display, packaging, ecommerce product pages, and retail media"}, {"id": "683019ab-2d8a-4983-944b-12ccaa8d3741", "type": "concept", "title": "Path-to-purchase, planogram context, and impulse behavior"}, {"id": "255a6c95-991a-4b0a-a3af-c7169507304f", "type": "concept", "title": "Trade-offs among margin, volume, brand health, and retailer goals"}], "description": "Students learn how IMC appears at the point of choice, both in-store and online."}]}, {"id": "eb97f1c7-bf4b-4c5f-b799-b90aeb0cefbe", "type": "topic", "title": "Direct Marketing, CRM and Lifecycle Communication", "description": "Direct and CRM channels let brands build relationships over time with measurable behavior. This unit teaches lifecycle thinking from first contact to loyalty and advocacy.", "children": [{"id": "7e0dea41-1551-41b9-8207-f7f2b8202590", "type": "subtopic", "title": "Direct Response Foundations", "children": [{"id": "1ebacd54-6333-427f-b70c-387f49d5a2c9", "type": "concept", "title": "Offers, lists, targeting, personalization, creative, timing, and response paths"}, {"id": "42dc09b2-b0e2-4128-87ba-ae2311850f1f", "type": "concept", "title": "Landing pages, forms, calls, QR codes, SMS, email, and mail"}, {"id": "b6ee09b9-57d1-4cc9-8664-5710bb635118", "type": "concept", "title": "Response rate, conversion rate, cost per acquisition, and revenue per send"}], "description": "Students learn how direct marketing differs from broad awareness communication."}, {"id": "c98df5fb-3533-4c41-8626-4fe2d4bed0cd", "type": "subtopic", "title": "CRM and Customer Lifecycle", "children": [{"id": "13482736-1d1f-4eb9-9c2c-a23ad27a14f0", "type": "concept", "title": "Acquisition, onboarding, activation, retention, winback, loyalty, and referral"}, {"id": "37c0db84-afae-427a-b63d-36d22090be39", "type": "concept", "title": "Lifecycle triggers, journeys, and nurture flows"}, {"id": "5491cdd1-dcc7-43cd-882c-2586306c6473", "type": "concept", "title": "Customer lifetime value and customer equity"}], "description": "The purpose is to map communication to customer states and relationship value."}, {"id": "e9dc56d4-dd8f-45cb-ad0c-97e793a11071", "type": "subtopic", "title": "Marketing Automation", "children": [{"id": "284a8d13-acab-4b7a-94ec-ff6b49ea64b9", "type": "concept", "title": "Segmentation logic, lead scoring, workflows, suppression, and frequency caps"}, {"id": "d0c622ee-0ff7-4e26-9ee1-893cc0000661", "type": "concept", "title": "Testing subject lines, offers, timing, and creative modules"}, {"id": "06b6c5fe-4ff8-4928-921d-466b6e0552f9", "type": "concept", "title": "Deliverability, consent, preference centers, and data quality"}], "description": "Students learn how automation scales relevance while requiring governance and restraint."}]}, {"id": "f5fe7ef8-0409-4350-8e2d-9d26dcd24d2b", "type": "topic", "title": "Experiential Marketing, Events and Sponsorship", "description": "Experiences can make a brand tangible, social, and memorable. This section teaches how events and sponsorships become strategic communication platforms rather than isolated activations.", "children": [{"id": "d1283ff5-8756-42bc-8852-619b9d74166b", "type": "subtopic", "title": "Experience Strategy", "children": [{"id": "eb06ca40-9aaa-43ff-ac02-5184982b9ec4", "type": "concept", "title": "Event objectives, audience journey, invitation, experience, follow-up"}, {"id": "995514a7-1eb8-4bf7-a0e0-a42dff3fa571", "type": "concept", "title": "Pop-ups, demos, conferences, sampling, community events, and virtual experiences"}, {"id": "5d923498-98b2-4c2e-8af3-27d045f53911", "type": "concept", "title": "Brand immersion, participation, and memory creation"}], "description": "Students learn to design live, digital, and hybrid experiences around audience value and brand meaning."}, {"id": "a7043609-3685-47b8-bbe4-13a7a00a0b6c", "type": "subtopic", "title": "Sponsorship and Partnerships", "children": [{"id": "3d6f1074-8791-483b-a7a7-041086ab333c", "type": "concept", "title": "Rights, assets, fit, activation plans, and exclusivity"}, {"id": "85ec3f2f-80d4-430d-9900-9de2410e25ba", "type": "concept", "title": "Sports, entertainment, culture, nonprofit, and campus sponsorships"}, {"id": "4abcdc8d-ba5b-4372-919e-699c8e344a04", "type": "concept", "title": "Co-marketing, partner governance, and value exchange"}], "description": "The focus is on aligning with properties, creators, organizations, or causes that transfer meaning to the brand."}, {"id": "75ac4dcb-b5f1-460f-a100-d6ae488840b5", "type": "subtopic", "title": "Measurement and Operations", "children": [{"id": "5508ad02-9200-4fe6-91ab-b084b42af7f4", "type": "concept", "title": "Attendance, leads, engagement, sentiment, sales lift, and media value"}, {"id": "bd301b8c-ab33-4900-9eca-40d8b09e5214", "type": "concept", "title": "Run-of-show, staffing, vendors, permits, logistics, and risk planning"}, {"id": "30199ef0-864d-455e-91b5-49d94565082c", "type": "concept", "title": "Post-event content, retargeting, and CRM integration"}], "description": "Students learn the practical discipline needed to prove value and execute well."}]}, {"id": "1d7b6506-d268-4c89-ad71-5bcd9498e841", "type": "topic", "title": "Influencer, Creator and Partnership Strategy", "description": "Creators and partners can provide credibility, cultural fluency, and distribution, but they also introduce brand safety and governance challenges. This unit teaches responsible creator-led IMC.", "children": [{"id": "eadbc4ca-c5db-4d97-8ed2-58e39e5e23a7", "type": "subtopic", "title": "Creator Fit and Selection", "children": [{"id": "ac39cd26-eb91-46b2-b5f5-8f4a3513e0d1", "type": "concept", "title": "Audience demographics, engagement quality, content fit, and credibility"}, {"id": "68c86f30-a84f-4b88-8103-ad2def7c7647", "type": "concept", "title": "Macro, mid-tier, micro, nano, expert, employee, and customer advocates"}, {"id": "c27f093e-7276-4554-9c8d-8d6a40291dcd", "type": "concept", "title": "Brand safety, past content review, and reputational risk"}], "description": "Students learn how to choose partners based on audience, trust, relevance, and brand alignment."}, {"id": "f7beae3d-a327-41ca-8b80-f959e4d921f0", "type": "subtopic", "title": "Collaboration and Content Governance", "children": [{"id": "bea3f563-883f-4fa1-91f6-3fe86cab6a89", "type": "concept", "title": "Briefs, creative freedom, approvals, usage rights, and exclusivity"}, {"id": "ca59ae46-cefb-4b55-8940-911a8f18a613", "type": "concept", "title": "Disclosure requirements, FTC guidance, and sponsored content clarity"}, {"id": "9e9037b3-340b-4a5f-a3ce-d1d18f40bf66", "type": "concept", "title": "Asset rights, whitelisting, boosting, and paid amplification"}], "description": "The goal is to balance creator authenticity with campaign strategy and compliance."}, {"id": "9faed263-303b-43e8-b49d-9a12dcb6ad10", "type": "subtopic", "title": "Creator Measurement", "children": [{"id": "48047384-602c-4671-ad84-7ff10e8696be", "type": "concept", "title": "Reach, engagement, click-through, conversion, lift, sentiment, and content reuse value"}, {"id": "49acaa3f-2faa-402f-a8c5-47ea116b2572", "type": "concept", "title": "Promo codes, UTM links, affiliate tracking, and incrementality tests"}, {"id": "647e65a2-946f-4720-b15f-5dd78f5164cb", "type": "concept", "title": "Learning across creator cohorts and formats"}], "description": "Students learn to assess creator work beyond vanity metrics."}]}, {"id": "e4489dcd-df40-4195-9200-a06bc54f9445", "type": "topic", "title": "Analytics, Attribution and Marketing ROI", "description": "World-class IMC treats measurement as a learning system, not a final report. This unit builds fluency in campaign metrics, dashboards, experiments, attribution, and ROI judgment.", "children": [{"id": "419a69f4-49fe-48d5-8e1f-5788d9f6b9a4", "type": "subtopic", "title": "Measurement Planning", "children": [{"id": "020853af-cc15-47c4-b0ec-b591f0ed214d", "type": "concept", "title": "Objectives, KPIs, targets, benchmarks, and decision rules"}, {"id": "839dffb6-c14e-475a-8c7f-26483d9909ae", "type": "concept", "title": "Input, output, outcome, and business-impact metrics"}, {"id": "0755e4d0-d907-4d91-af46-152029385310", "type": "concept", "title": "Measurement briefs, tagging plans, and dashboard design"}], "description": "Students learn to define success before launch so every tactic has a measurement role."}, {"id": "dbace122-1d80-4dfa-a4cc-8fa73fc85d19", "type": "subtopic", "title": "Attribution and Incrementality", "children": [{"id": "d630ba90-1d6d-4f55-9d84-48b20e317388", "type": "concept", "title": "Last-click, multi-touch, marketing mix modeling, geo tests, holdouts, and lift studies"}, {"id": "26581fc9-cf35-47e5-9f77-16cbfb37308e", "type": "concept", "title": "Correlation versus causation and common attribution bias"}, {"id": "33856856-deeb-42af-8d1f-dae51c11b3f7", "type": "concept", "title": "Privacy changes, cookie loss, walled gardens, and modeled conversions"}], "description": "The point is to understand what can and cannot be claimed from campaign data."}, {"id": "f75579b5-ac33-4593-b4bc-195def4f8bf3", "type": "subtopic", "title": "ROI and Learning Loops", "children": [{"id": "74912103-a45e-4928-b6d4-87a0c8a51f2b", "type": "concept", "title": "ROI, ROAS, CAC, LTV, payback, marginal return, and diminishing returns"}, {"id": "d089feb0-4997-42ae-bd7e-4826c34750cf", "type": "concept", "title": "Creative, audience, offer, channel, and landing page diagnostics"}, {"id": "de397093-8f26-4dcc-a933-c4eae9b46f3a", "type": "concept", "title": "Post-campaign analysis, recommendations, and knowledge management"}], "description": "Students learn how to interpret performance in a way that improves future strategy."}]}, {"id": "23ac4bc1-98bc-41aa-afab-cdcf2ae069d0", "type": "topic", "title": "Budgeting, Forecasting and Resource Allocation", "description": "IMC decisions are constrained by budget, time, talent, and risk. This section teaches students how to allocate resources with financial discipline and strategic intent.", "children": [{"id": "549d4a3c-0b9f-4434-80c4-e6f5c2493902", "type": "subtopic", "title": "Budgeting Methods", "children": [{"id": "467128f9-a224-40f5-893a-51587f438dcf", "type": "concept", "title": "Objective-and-task, percentage-of-sales, competitive parity, affordability, and experimental budgets"}, {"id": "e1782f09-1c9c-4654-bd7c-e9071a4d6727", "type": "concept", "title": "Working versus non-working media costs"}, {"id": "28ae84b1-f52b-4d72-932b-9c6c641c5812", "type": "concept", "title": "Production, agency, technology, talent, research, and contingency costs"}], "description": "Students learn common ways organizations set communication budgets and the trade-offs each creates."}, {"id": "bf58c301-069b-4960-ac72-2798debe3222", "type": "subtopic", "title": "Forecasting Campaign Results", "children": [{"id": "fff45461-5f8f-4f0e-84f4-70571506731f", "type": "concept", "title": "Reach, response, conversion, revenue, margin, and lifetime value assumptions"}, {"id": "97aeced0-af60-490d-98a2-bced21c11613", "type": "concept", "title": "Scenario planning and sensitivity analysis"}, {"id": "9781f85e-0c3f-49d7-b86d-826905ee62d5", "type": "concept", "title": "Expected value and risk-adjusted campaign choices"}], "description": "The aim is to make campaign plans testable before money is committed."}, {"id": "48f1c5d4-11b6-4eac-8614-03fe8e2df0b1", "type": "subtopic", "title": "Resource Allocation", "children": [{"id": "a15712d4-cc8c-4ead-81d0-ff750fb16a14", "type": "concept", "title": "Portfolio balance between brand and performance"}, {"id": "d869f288-fe9d-4ad7-af3a-6bf4d18b6dbe", "type": "concept", "title": "Marginal return, saturation, and budget reallocation"}, {"id": "7714aa98-0ff7-43ed-89c5-3eec4b365275", "type": "concept", "title": "Governance for mid-campaign optimization"}], "description": "Students learn to distribute spend across audiences, channels, creative, and time."}]}, {"id": "c59d4550-9c57-4c9b-a5db-2faf57ef61e8", "type": "topic", "title": "Legal, Ethical, Privacy and Inclusive Communication", "description": "IMC operates in a trust environment shaped by law, platform policy, data use, representation, and social responsibility. This section makes ethical judgment part of campaign quality.", "children": [{"id": "52112339-05f9-4f1e-9922-3d5c7a091675", "type": "subtopic", "title": "Advertising Law and Claims", "children": [{"id": "25c4224f-b9f5-4f1b-a52e-c6ca8c8ff26d", "type": "concept", "title": "Claim substantiation, comparative advertising, endorsements, disclosures, and native advertising"}, {"id": "d84507e0-88c2-432a-9f25-29871ca96127", "type": "concept", "title": "FTC, platform policies, industry self-regulation, and brand review processes"}, {"id": "bd74a3bf-2ab0-4aed-b906-d4afd5be2333", "type": "concept", "title": "Regulated categories and high-risk claims"}], "description": "Students learn the basic guardrails for truthful, substantiated, and non-deceptive communication."}, {"id": "94b8510e-0d05-48d5-85ca-0f2efb26c86c", "type": "subtopic", "title": "Privacy and Responsible Personalization", "children": [{"id": "26a49abb-2d72-466d-8736-1d1e37018923", "type": "concept", "title": "Consent, preference management, data minimization, security, and retention"}, {"id": "688c916a-d45a-47f6-be49-67e5c8ef05bd", "type": "concept", "title": "Sensitive data, vulnerable audiences, children, and health/financial inferences"}, {"id": "55b95c70-fa92-40b2-8148-0985f44a34e8", "type": "concept", "title": "Measurement loss, clean rooms, and privacy-preserving analytics"}], "description": "The point is to use data in ways that preserve consent, dignity, and trust."}, {"id": "565d39e7-9c7d-4383-926d-1e91f6b136b0", "type": "subtopic", "title": "Inclusive and Ethical Communication", "children": [{"id": "c23a8e11-8272-4329-b0fb-fdaec8759e53", "type": "concept", "title": "Stereotypes, cultural appropriation, tokenism, and bias in targeting"}, {"id": "7458b043-e890-442f-bc76-380438079dfa", "type": "concept", "title": "Accessibility in copy, visuals, video, color, captions, and UX"}, {"id": "673dd665-d3c4-435f-aec0-e154cbc47aee", "type": "concept", "title": "Sustainability, social claims, and avoiding purpose-washing"}], "description": "Students learn to evaluate representation, accessibility, and social impact with rigor."}]}, {"id": "651ec6ee-4915-4081-8a11-790c347292b5", "type": "topic", "title": "Campaign Operations, Agency Collaboration and Client Presentation", "description": "Excellent strategy must survive real execution. This unit teaches the workflow, collaboration, presentation, and decision skills that make IMC campaigns operationally credible.", "children": [{"id": "ed3e1d5a-7db5-4e01-b3dd-732181256ba8", "type": "subtopic", "title": "Campaign Workflow", "children": [{"id": "198485c2-cf47-46d0-8050-ec7da781ad4a", "type": "concept", "title": "Schedules, milestones, status systems, review rounds, and launch checklists"}, {"id": "c5750d08-7ca8-4024-96e9-83f5166139f0", "type": "concept", "title": "Creative, media, PR, legal, analytics, sales, and product coordination"}, {"id": "b1079e9a-a6db-465b-b759-559f3b65e54b", "type": "concept", "title": "Asset trafficking, QA, naming conventions, and handoff discipline"}], "description": "Students learn how campaign work moves from brief to launch to optimization to post-analysis."}, {"id": "8dd9069a-f568-47f0-ae74-74915dce7762", "type": "subtopic", "title": "Agency and Vendor Collaboration", "children": [{"id": "01840645-0652-4d82-952d-0a654dbac313", "type": "concept", "title": "Scopes of work, deliverables, roles, fees, timelines, and change management"}, {"id": "22c36ff5-288a-4333-b3f6-508ffe276851", "type": "concept", "title": "Briefings, feedback protocols, approvals, and accountability"}, {"id": "505e870a-8dae-4d1f-8101-17feab5798b6", "type": "concept", "title": "Procurement, rights, confidentiality, and performance review"}], "description": "The focus is on working professionally with agencies, freelancers, media partners, and internal teams."}, {"id": "91475e3e-e52d-450f-a71d-a1e8084adcdb", "type": "subtopic", "title": "Client and Executive Presentation", "children": [{"id": "307e3ce7-a8c6-49c4-b69d-64fdd9a9e36c", "type": "concept", "title": "Narrative structure, strategic rationale, evidence, and trade-offs"}, {"id": "f6e5edbc-ca86-4807-afc3-1199a65d386b", "type": "concept", "title": "Visualizing plans, budgets, journey maps, and dashboards"}, {"id": "52cfef63-941b-427e-b05e-08456db23832", "type": "concept", "title": "Handling objections, defending assumptions, and documenting decisions"}], "description": "Students learn to make campaign recommendations clear, persuasive, and decision-ready."}]}, {"id": "1269c111-a7e1-49db-8c65-bd30a02e8758", "type": "topic", "title": "Capstone Integrated Campaign Plan", "description": "The course culminates in a professional integrated campaign plan. Students synthesize research, strategy, creative, media, PR, digital, budget, measurement, ethics, and presentation into one coherent recommendation.", "children": [{"id": "ddb82b2e-f6dd-48cf-8746-87a2b9cfc9bf", "type": "subtopic", "title": "Campaign Diagnosis and Brief", "children": [{"id": "102178be-1e20-40fd-8f72-8aaaf288e308", "type": "concept", "title": "Situation analysis, brand audit, customer insight, competitor review, and opportunity definition"}, {"id": "9c9f8038-6d0f-41ef-81c1-f0c8bfe06e95", "type": "concept", "title": "Campaign objective, target audience, positioning, and key message"}, {"id": "4d27f3f0-a6e1-48ed-962f-6852b7209e16", "type": "concept", "title": "Success metrics, constraints, assumptions, and risks"}], "description": "Students begin by identifying the marketing problem and translating it into a strong IMC brief."}, {"id": "bb2bb652-8d5a-450a-8b45-b70c0af23ca4", "type": "subtopic", "title": "Integrated Plan Development", "children": [{"id": "d09ae7a0-4ae7-4e65-84cc-a72d6d483a81", "type": "concept", "title": "Creative platform, message map, channel mix, media calendar, PR plan, content system, CRM flow, and activation plan"}, {"id": "8fda658f-3aef-4d8b-8aaa-fc2d7b5b1798", "type": "concept", "title": "Budget allocation, production plan, staffing, and timeline"}, {"id": "2afd0269-161f-4be5-9171-562fb92f8a65", "type": "concept", "title": "Legal, ethical, accessibility, privacy, and inclusion review"}], "description": "The capstone requires students to design a coordinated campaign across channels and moments."}, {"id": "4c2acaaa-1de3-4ec2-86d3-24b88454990e", "type": "subtopic", "title": "Pitch, Measurement and Reflection", "children": [{"id": "2cf05071-7845-4da3-a4ce-8a089320a28c", "type": "concept", "title": "Executive pitch deck, campaign rationale, and decision asks"}, {"id": "272d68db-5110-4020-803d-6dd7883e26e4", "type": "concept", "title": "Dashboard mockup, attribution plan, experiment design, and ROI forecast"}, {"id": "db73d96f-b2c3-4670-8d24-4b6ac9072f70", "type": "concept", "title": "Post-pitch critique, revisions, and individual learning memo"}], "description": "Students finish by presenting the campaign and explaining how it will be evaluated and improved."}]}], "dbBacked": true}$imcjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'integrated-marketing-communications'
);

update public.learning_paths
set
  title = 'Integrated Marketing Communications',
  goal = 'Integrated Marketing Communications',
  summary = 'Integrated Marketing Communications teaches students how to design coordinated, measurable, and ethically responsible campaigns across advertising, public relations, digital, social, direct, experiential, sponsorship, retail, and owned media. Students learn to move from business problem to customer insight, positioning, creative brief, media plan, budget, execution workflow, and performance dashboard. The course is built around professional campaign practice: every communication choice must have a strategic reason, a defined audience, a clear message role, and a measurable learning plan.',
  data = $imcjson${"slug": "integrated-marketing-communications", "title": "Integrated Marketing Communications", "description": "Integrated Marketing Communications teaches students how to design coordinated, measurable, and ethically responsible campaigns across advertising, public relations, digital, social, direct, experiential, sponsorship, retail, and owned media. Students learn to move from business problem to customer insight, positioning, creative brief, media plan, budget, execution workflow, and performance dashboard. The course is built around professional campaign practice: every communication choice must have a strategic reason, a defined audience, a clear message role, and a measurable learning plan.", "topics": [{"id": "731f90e1-bbee-499e-b837-8d8c235f21a3", "type": "topic", "title": "IMC Strategy and Campaign Architecture", "description": "This opening unit frames IMC as a disciplined system for aligning brand, audience, message, channel, and measurement. Students learn to turn business goals into coordinated communication choices rather than isolated tactics.", "children": [{"id": "def39c07-c172-4e12-95aa-85a72a58b347", "type": "subtopic", "title": "Strategic Role of IMC", "children": [{"id": "c9ad6f37-20b5-45a9-bccb-a8a311f19e2b", "type": "concept", "title": "Business goals, communication goals, and behavioral objectives"}, {"id": "21d88f55-9695-4f2d-bd5d-296864bd20b0", "type": "concept", "title": "Brand consistency across paid, owned, earned, shared, and retail channels"}, {"id": "2c53d32a-be8c-48be-a92a-98598f911935", "type": "concept", "title": "Integration across advertising, PR, direct, sales, social, content, and events"}], "description": "The goal is to understand why integrated communications matter: they reduce message fragmentation and make every customer touchpoint reinforce a coherent market position."}, {"id": "4cfd7709-a9b6-459b-badd-eb7beec2feb8", "type": "subtopic", "title": "Campaign Planning Models", "children": [{"id": "4ec84146-2003-4b40-9975-330bfd80e9a2", "type": "concept", "title": "Situation analysis, audience insight, objectives, strategy, tactics, action, control"}, {"id": "ce156cfa-942f-44f1-b5e6-2367819d0e92", "type": "concept", "title": "Brief-to-execution workflow and approval gates"}, {"id": "e5ec1b60-52c8-4f4d-9825-88f419965658", "type": "concept", "title": "Campaign maps that connect message, channel, timing, and measurement"}], "description": "Students learn practical planning models that convert ambiguity into an organized campaign logic."}, {"id": "31e88dce-5569-4b57-81f3-2f25ead47497", "type": "subtopic", "title": "Professional IMC Standards", "children": [{"id": "adec8e0e-0208-4b06-88aa-16d639461c70", "type": "concept", "title": "Evidence-based strategy rather than channel-first execution"}, {"id": "ce379ae1-09ec-4df1-9cfa-a1e988ba471d", "type": "concept", "title": "Cross-functional collaboration among brand, media, analytics, product, and sales"}, {"id": "9440eb71-ade1-499b-9d24-7e2822a9c3af", "type": "concept", "title": "Portfolio thinking across short-term activation and long-term brand building"}], "description": "This subtopic sets the bar for professional campaign thinking in top marketing programs and agencies."}]}, {"id": "802fa105-53c0-4c5c-b6c7-80afd68df0df", "type": "topic", "title": "Customer Insight, Segmentation, Targeting and Positioning", "description": "IMC becomes powerful when it is grounded in a precise view of customers and the market. This section develops the insight work behind who the campaign serves and what distinctive meaning it should own.", "children": [{"id": "d62b5a6e-ee50-412d-9048-1da1b6477010", "type": "subtopic", "title": "Customer and Market Insight", "children": [{"id": "102533dd-6747-4df9-9450-a45822d88d85", "type": "concept", "title": "Jobs-to-be-done, motivations, barriers, and triggers"}, {"id": "aca564c9-23ab-4c96-9cac-3b3c8ddad22c", "type": "concept", "title": "Category entry points and moments of need"}, {"id": "9acb4552-4a25-4128-9220-1f94665201f4", "type": "concept", "title": "Voice-of-customer, social listening, search behavior, and review mining"}], "description": "Students learn to move from demographic description to sharper human, behavioral, cultural, and category insight."}, {"id": "3396ce21-73c0-40b6-9d79-365a64461efe", "type": "subtopic", "title": "Segmentation and Targeting", "children": [{"id": "10d4346a-f9e3-4bad-890b-b550e14f7a4f", "type": "concept", "title": "Behavioral, psychographic, firmographic, and value-based segmentation"}, {"id": "515ff48a-23e6-4184-bd53-410009f6e04e", "type": "concept", "title": "Target attractiveness, accessibility, and strategic fit"}, {"id": "c002b902-fb0a-4d2a-8d14-b1b119668993", "type": "concept", "title": "Primary, secondary, influencer, and internal stakeholder audiences"}], "description": "The purpose is to choose valuable audiences deliberately instead of trying to speak to everyone at once."}, {"id": "d9cc0c33-3995-4522-8188-eafa2cb46809", "type": "subtopic", "title": "Positioning and Value Proposition", "children": [{"id": "41a63e76-e3e9-4266-b915-24f1bebc94df", "type": "concept", "title": "Points of parity and points of difference"}, {"id": "3ecc864b-cdd3-4acb-bcac-e0f2672f5821", "type": "concept", "title": "Positioning statements and value propositions"}, {"id": "60c79ef9-fe2b-445c-bab7-2bf7547b0f3a", "type": "concept", "title": "Competitor mapping, perceptual maps, and white-space analysis"}], "description": "Students learn how a campaign should sharpen what the brand means and why that meaning matters."}]}, {"id": "689bcfc4-f770-4e67-a350-14ee942af06b", "type": "topic", "title": "Brand Identity, Equity and Message Consistency", "description": "Integrated communications must protect and grow brand equity. This unit connects visual identity, verbal identity, positioning, memory structures, and trust.", "children": [{"id": "fb824f76-c470-42d2-b7d4-430ae1a4defa", "type": "subtopic", "title": "Brand Identity Systems", "children": [{"id": "c2eb4989-1aeb-455c-ab41-f1ceb3fbdb09", "type": "concept", "title": "Name, logo, color, typography, voice, tone, and sonic cues"}, {"id": "a6b4338c-1fab-4462-ac31-92beae42f7cb", "type": "concept", "title": "Brand guidelines, governance, and approval systems"}, {"id": "a1c50d8a-e44f-48d7-954c-bee8834b480f", "type": "concept", "title": "Adaptation across formats without losing coherence"}], "description": "Students learn the elements that make a brand recognizable and usable across every channel."}, {"id": "ec895059-cf8e-425d-92b5-c5388f0eeeb1", "type": "subtopic", "title": "Brand Equity and Mental Availability", "children": [{"id": "8fc4f80d-5b36-443c-b43b-babdbdb4ea70", "type": "concept", "title": "Awareness, associations, perceived quality, loyalty, and differentiation"}, {"id": "4676de5a-e391-48a2-b96a-809f0259b0cf", "type": "concept", "title": "Distinctive brand assets and category cues"}, {"id": "d5254ab8-ebab-45f9-a48e-cdc60daf1893", "type": "concept", "title": "Long-term brand building versus short-term conversion"}], "description": "The gist is that communication builds memory, salience, associations, and preference over time."}, {"id": "84d06fdc-012b-4b90-af32-7c0c12bd8649", "type": "subtopic", "title": "Message Consistency and Variation", "children": [{"id": "31da60d4-8123-48c8-b2ec-584d19e36842", "type": "concept", "title": "Message hierarchy and proof architecture"}, {"id": "d5519d12-3bb5-4a47-b7e2-65337e6a247f", "type": "concept", "title": "Core claims, reasons to believe, and supporting evidence"}, {"id": "d032c4db-5d22-4cbe-ae81-caa3555d48cc", "type": "concept", "title": "Audience, channel, and funnel adaptations"}], "description": "Students learn to distinguish strategic consistency from repetitive sameness."}]}, {"id": "cc00ca58-4faf-42ab-9bb3-14149ba2693b", "type": "topic", "title": "The Creative Brief and Big Idea", "description": "A strong brief is the bridge between strategy and creative work. This section teaches students how to express the problem, audience, promise, evidence, tone, and constraints in a way that unlocks great execution.", "children": [{"id": "d2a71148-e94b-433f-b08d-1f0d46428302", "type": "subtopic", "title": "Creative Brief Foundations", "children": [{"id": "eb07fc70-bc5d-4645-ba45-de03d44ff3ae", "type": "concept", "title": "Problem statement, objective, audience, insight, proposition, support, tone, mandatories"}, {"id": "baea307b-72ad-41f6-a501-b51c803b68cf", "type": "concept", "title": "Single-minded message and creative tension"}, {"id": "266c3d24-651a-4c18-9304-1c2cefd7cdd2", "type": "concept", "title": "Evaluation criteria for whether the idea answers the brief"}], "description": "Students learn what a brief must contain and why vague briefs lead to weak campaigns."}, {"id": "089d6e6b-0afe-4dfe-ad10-8a2b232bf10f", "type": "subtopic", "title": "The Big Idea", "children": [{"id": "ffb49a27-d7fd-4936-97c3-95adb9104646", "type": "concept", "title": "Central campaign thought and strategic hook"}, {"id": "58b4cba5-eda9-45d6-b8d2-68a756390f99", "type": "concept", "title": "Concept testing and stress-testing across channels"}, {"id": "460bd16b-0d70-4e8f-aa8c-fc7d80eb55e0", "type": "concept", "title": "Distinctiveness, emotional resonance, usefulness, and shareability"}], "description": "This subtopic focuses on campaign concepts that travel across media while staying memorable."}, {"id": "bcad289d-b976-456b-b581-4515468e59b4", "type": "subtopic", "title": "Creative Review and Feedback", "children": [{"id": "768eddbc-3352-4f1e-8f5c-c74b2490eb32", "type": "concept", "title": "Feedback language for message, brand fit, clarity, originality, and feasibility"}, {"id": "206bdaec-9b11-4191-860d-48f820754792", "type": "concept", "title": "Iteration cycles from thumbnails to scripts to prototypes"}, {"id": "dbc2b80a-057c-4010-a094-2f0348266920", "type": "concept", "title": "Avoiding committee dilution and preserving strategic intent"}], "description": "Students learn how to critique creative work against strategy instead of personal taste."}]}, {"id": "ef25ff45-e634-45b2-bc32-856cdee07d97", "type": "topic", "title": "Advertising Strategy and Persuasive Communication", "description": "Advertising remains a central IMC tool because it can shape awareness, memory, emotion, and demand at scale. This unit connects persuasion theory with practical campaign design.", "children": [{"id": "ad199b64-9fd4-4ea6-828e-3b8d668d9400", "type": "subtopic", "title": "Persuasion and Message Strategy", "children": [{"id": "2d53577a-d795-4309-b1e5-2bf8ee19f524", "type": "concept", "title": "Ethos, pathos, logos, social proof, scarcity, authority, and reciprocity"}, {"id": "1cbfaf39-3bb0-4483-9cef-a68f606f1014", "type": "concept", "title": "Elaboration likelihood, framing, priming, and fluency"}, {"id": "1f2c8d9e-8f93-4551-b9f4-98311c89ddf2", "type": "concept", "title": "Rational, emotional, transformational, comparative, and reminder appeals"}], "description": "Students learn how communication influences attention, comprehension, attitude, intention, and action."}, {"id": "242d1dd6-9c12-4a66-877b-304890186a2d", "type": "subtopic", "title": "Advertising Objectives", "children": [{"id": "b12cc067-6778-4b7c-a7e4-75d703f5eadd", "type": "concept", "title": "Awareness, consideration, preference, trial, repeat purchase, loyalty, and advocacy"}, {"id": "25ade7ec-0379-4c51-a339-e9c4fbe1b164", "type": "concept", "title": "Category creation, repositioning, launch, defense, and growth objectives"}, {"id": "b9758ce2-a451-4ea9-b4c9-7b9777bd8c04", "type": "concept", "title": "Behavioral outcomes versus communication outcomes"}], "description": "The point is to choose the right advertising job before choosing the advertisement."}, {"id": "af33520a-414a-4aa6-b5c3-9382c4dc49e3", "type": "subtopic", "title": "Executional Formats", "children": [{"id": "b98d88a0-0d97-4df9-92f0-3ffdc373655c", "type": "concept", "title": "Demonstration, testimonial, slice-of-life, problem-solution, story, humor, and comparison"}, {"id": "050b20f9-a1bb-433c-a3f9-bfc086f2d722", "type": "concept", "title": "Copy platforms, scripts, storyboards, and key visuals"}, {"id": "6ad2382b-97e6-4bd1-ae85-553f5144f64e", "type": "concept", "title": "Claims support, substantiation, and responsible persuasion"}], "description": "Students learn the craft options that turn strategy into attention-worthy communication."}]}, {"id": "925c3b4b-e3e9-4b9f-8d13-a951786a0a78", "type": "topic", "title": "Creative Development, Copywriting and Art Direction", "description": "Creative execution determines whether strategy becomes vivid enough for people to notice, understand, and remember. This section trains the craft layer of IMC.", "children": [{"id": "560ef1a5-114d-44ae-a075-d536cdead579", "type": "subtopic", "title": "Copywriting for Campaigns", "children": [{"id": "ea45f5d0-e764-40b1-a901-76c4d5160af9", "type": "concept", "title": "Headlines, taglines, body copy, captions, scripts, subject lines, and CTAs"}, {"id": "12cc6a13-9f52-42c3-873a-2e4dab156bd5", "type": "concept", "title": "Clarity, brevity, specificity, rhythm, and tone"}, {"id": "d0ceaa56-96e3-4bbb-9c3f-1c83c3613578", "type": "concept", "title": "Writing for different funnel stages and formats"}], "description": "Students learn how words move from headline to call-to-action while carrying the brand's voice."}, {"id": "cde562e4-2588-4a37-8024-36b30719dcc5", "type": "subtopic", "title": "Art Direction and Visual Storytelling", "children": [{"id": "830f3fba-cd8e-4b28-9f0c-8fab4e040db4", "type": "concept", "title": "Composition, hierarchy, color, imagery, typography, and motion cues"}, {"id": "4de1cac7-ec29-4c2c-8bc5-4f36b6af263c", "type": "concept", "title": "Brand asset use across print, digital, video, and outdoor"}, {"id": "2169bff3-8ef3-4566-9c53-bfa0f9af7fda", "type": "concept", "title": "Accessibility, legibility, and mobile-first visual design"}], "description": "The aim is to understand how design choices communicate before the audience reads a word."}, {"id": "c9be6bac-7b00-4db7-a14f-5f51e5f6af68", "type": "subtopic", "title": "Production and Adaptation", "children": [{"id": "76bf164a-8654-4c34-9537-3f98da0b1433", "type": "concept", "title": "Asset matrices, deliverable lists, localization, and resizing"}, {"id": "12331290-9290-4881-8eca-57cf1302d6b2", "type": "concept", "title": "Photography, video, motion, audio, and design production basics"}, {"id": "e550b009-d318-49cb-b603-1e500844fc02", "type": "concept", "title": "Versioning for audiences, platforms, placements, and tests"}], "description": "Students learn to manage creative work across formats, deadlines, budgets, and technical specs."}]}, {"id": "ad69ecc2-ded8-4396-85a7-a99e512e879d", "type": "topic", "title": "Media Planning, Buying and Channel Mix", "description": "A great message fails if it reaches the wrong people in the wrong context. This unit teaches how media choices translate objectives into reach, frequency, impact, and efficiency.", "children": [{"id": "29bdcf22-8d34-44e3-bb4a-322d1848dad8", "type": "subtopic", "title": "Media Objectives and Metrics", "children": [{"id": "4f894d74-53b3-4103-afaf-b9a76111e62a", "type": "concept", "title": "Reach, frequency, GRPs, impressions, CPM, CPC, CPA, viewability, and completion rate"}, {"id": "b3055f04-0984-4942-93a5-0068a1edab02", "type": "concept", "title": "Audience quality, context, timing, and duplication"}, {"id": "f12e98f2-d430-4e2f-8fdb-780f5f93f963", "type": "concept", "title": "Effective frequency and diminishing returns"}], "description": "Students learn the language of media planning so they can connect exposure to outcomes."}, {"id": "d09893b9-9647-4abe-993a-32fdb55e5884", "type": "subtopic", "title": "Channel Mix Strategy", "children": [{"id": "b06b7101-a651-4ac2-b927-be7b0fa9c765", "type": "concept", "title": "Television, streaming, audio, print, out-of-home, search, social, display, email, influencer, PR, events"}, {"id": "b0fa4255-cb49-43c0-b222-cae3b59740db", "type": "concept", "title": "Funnel role and customer journey fit by channel"}, {"id": "a735c3aa-540f-41ff-8a62-8ef9f8c7d177", "type": "concept", "title": "Integrated flighting, pulsing, sequencing, and always-on media"}], "description": "This subtopic explains how paid, owned, earned, shared, retail, and partner channels work together."}, {"id": "eaf3f422-9b2d-455e-b2fc-141f7e94b239", "type": "subtopic", "title": "Buying and Optimization", "children": [{"id": "d47bfa5b-d0e1-4640-9631-d131ad7f97b0", "type": "concept", "title": "Briefing media partners and evaluating proposals"}, {"id": "d39bfab4-78d7-4456-bea5-d765bc3674a6", "type": "concept", "title": "Programmatic, direct buys, sponsorships, and marketplace dynamics"}, {"id": "2940c0f0-f3d4-4061-8c78-69c43ffd2c44", "type": "concept", "title": "Budget pacing, bid strategy, creative rotation, and optimization rules"}], "description": "Students learn the operational side of turning plans into real placements and learning cycles."}]}, {"id": "0b2d0b81-ed05-4d58-9e01-3ba43ee5d4d6", "type": "topic", "title": "Digital, Social and Content IMC", "description": "Digital channels make integration more complex because messages can be targeted, personalized, measured, shared, and remixed. This section builds a modern platform-aware communication toolkit.", "children": [{"id": "9ee3d53e-ea53-4040-aef3-ad7ae3db502c", "type": "subtopic", "title": "Platform Strategy", "children": [{"id": "88be2973-b448-48ae-aab5-c65b0757512b", "type": "concept", "title": "Search, social, video, display, retail media, messaging, communities, and creators"}, {"id": "79fe921d-da5a-4193-9a71-52cfab83f0c9", "type": "concept", "title": "Platform-native formats, algorithms, and attention patterns"}, {"id": "93a11944-069a-4335-9be4-7f15e0cb74f6", "type": "concept", "title": "Organic, paid, and boosted distribution"}], "description": "Students learn that each platform has its own audience behavior, creative grammar, and measurement limits."}, {"id": "af8ae819-40c6-4e59-9ef7-ea054a5f15d6", "type": "subtopic", "title": "Content Systems", "children": [{"id": "8df33451-11d8-442d-b7db-797aada6c162", "type": "concept", "title": "Content pillars, editorial calendars, atomization, and repurposing"}, {"id": "a6a60eba-1a9d-4884-b676-6213592a3d65", "type": "concept", "title": "Hero, hub, help, and always-on content models"}, {"id": "67ae9286-e15e-470c-ba75-c440374f4e04", "type": "concept", "title": "SEO, social search, discoverability, and content governance"}], "description": "The point is to manage content as a strategic system rather than a calendar of disconnected posts."}, {"id": "6b76f004-aa67-431d-bd81-c71fb9468210", "type": "subtopic", "title": "Social Engagement and Community", "children": [{"id": "25b74eb6-b45f-419d-afb6-ad731a482e78", "type": "concept", "title": "Community management, response protocols, and moderation"}, {"id": "1efeca61-0d45-414e-b30f-7fef5ba13377", "type": "concept", "title": "User-generated content, advocacy, and social proof"}, {"id": "b8597550-0a5b-45ae-ba03-a0bc7682d2e3", "type": "concept", "title": "Listening, sentiment, cultural timing, and escalation"}], "description": "Students learn how IMC changes when audiences can respond, organize, critique, and co-create."}]}, {"id": "1abff898-2e4a-4795-97f3-b9f8ed037c73", "type": "topic", "title": "Public Relations, Reputation and Issues Management", "description": "PR connects campaigns to credibility, stakeholders, and the public conversation. This unit teaches how earned influence and reputation work alongside paid and owned media.", "children": [{"id": "f41e1e38-57cb-4eb1-965a-4376838f3384", "type": "subtopic", "title": "PR Strategy and Media Relations", "children": [{"id": "0d54e47f-76e4-4d80-8a56-908cb1703f72", "type": "concept", "title": "Press releases, pitches, media lists, briefings, and embargoes"}, {"id": "843f4d56-8d0d-4e59-8a05-ffe3f97de8e5", "type": "concept", "title": "News values, spokesperson preparation, and message discipline"}, {"id": "d7a05ff2-2d49-4efb-9373-170d54151684", "type": "concept", "title": "Earned media integration with paid and owned assets"}], "description": "Students learn how to earn attention through news value, relevance, and relationship building."}, {"id": "ba41671d-343d-4631-9454-5fb33044b93a", "type": "subtopic", "title": "Stakeholder Communication", "children": [{"id": "1874a55e-f10a-4939-89ad-3beb7a26ddf5", "type": "concept", "title": "Employees, investors, regulators, communities, partners, and advocacy groups"}, {"id": "c8ffd24c-1b21-45fd-97b3-62ceda50169b", "type": "concept", "title": "Internal alignment and executive communication"}, {"id": "87cbf7b4-322f-4ef6-a10e-2a4ddfd44717", "type": "concept", "title": "Corporate social responsibility and social impact claims"}], "description": "The focus is on audiences beyond customers who shape brand legitimacy and risk."}, {"id": "82dc67cb-c482-43c1-a41e-4fcf8f8a3701", "type": "subtopic", "title": "Issues and Crisis Response", "children": [{"id": "d8fafe19-1e4a-404c-bd27-382beaacfd6e", "type": "concept", "title": "Risk mapping, scenarios, holding statements, and escalation trees"}, {"id": "a7a76a1f-b530-40c3-bc4c-6b084ded1408", "type": "concept", "title": "Apology, correction, transparency, and accountability"}, {"id": "3cb83dd0-0a19-4375-977c-c148612409b7", "type": "concept", "title": "Monitoring, misinformation, and post-crisis learning"}], "description": "Students learn how to communicate when trust, safety, or reputation is under pressure."}]}, {"id": "588d0ec2-ea13-4eb3-b2f0-6ede27bec0ab", "type": "topic", "title": "Sales Promotion, Retail and Shopper Marketing", "description": "Promotions can stimulate action quickly, but they must be designed carefully so they do not erode brand equity or margins. This section connects shopper psychology with activation discipline.", "children": [{"id": "9c86af2a-2ace-42d8-afc8-d147ba6ab41b", "type": "subtopic", "title": "Promotion Objectives", "children": [{"id": "01158f93-cd76-48d2-965c-334e91ce6c1f", "type": "concept", "title": "Trial, repeat, stock-up, switching, traffic, basket size, and loyalty"}, {"id": "571f8d7b-adfb-4804-932e-cb8f68c4431e", "type": "concept", "title": "Consumer promotions, trade promotions, and channel incentives"}, {"id": "2dfc6e11-cfa2-44ef-a760-27fc41065364", "type": "concept", "title": "Promo calendars, seasonality, and campaign integration"}], "description": "Students learn when promotions are appropriate and what business problem they should solve."}, {"id": "8bc2de7e-ecf5-4c57-bdce-c602437c4c40", "type": "subtopic", "title": "Offer Design and Behavioral Triggers", "children": [{"id": "df2f18f0-e3fc-4e29-a399-d71d71060c89", "type": "concept", "title": "Coupons, rebates, bundles, samples, contests, sweepstakes, and loyalty rewards"}, {"id": "b24d23d4-51e8-4121-bd94-89e5319c4c90", "type": "concept", "title": "Urgency, scarcity, thresholds, framing, and reference price effects"}, {"id": "c9dccf82-909e-4b40-a24c-b7bb0c934ea3", "type": "concept", "title": "Legal, ethical, and fairness considerations"}], "description": "The gist is that promotion mechanics shape perceived value and action."}, {"id": "8b1afa6b-1956-446d-992a-93fb73e00bd0", "type": "subtopic", "title": "Retail and Shopper Communication", "children": [{"id": "faf30aaa-9a3a-479e-9b22-6fce5bf80911", "type": "concept", "title": "Shelf, display, packaging, ecommerce product pages, and retail media"}, {"id": "683019ab-2d8a-4983-944b-12ccaa8d3741", "type": "concept", "title": "Path-to-purchase, planogram context, and impulse behavior"}, {"id": "255a6c95-991a-4b0a-a3af-c7169507304f", "type": "concept", "title": "Trade-offs among margin, volume, brand health, and retailer goals"}], "description": "Students learn how IMC appears at the point of choice, both in-store and online."}]}, {"id": "eb97f1c7-bf4b-4c5f-b799-b90aeb0cefbe", "type": "topic", "title": "Direct Marketing, CRM and Lifecycle Communication", "description": "Direct and CRM channels let brands build relationships over time with measurable behavior. This unit teaches lifecycle thinking from first contact to loyalty and advocacy.", "children": [{"id": "7e0dea41-1551-41b9-8207-f7f2b8202590", "type": "subtopic", "title": "Direct Response Foundations", "children": [{"id": "1ebacd54-6333-427f-b70c-387f49d5a2c9", "type": "concept", "title": "Offers, lists, targeting, personalization, creative, timing, and response paths"}, {"id": "42dc09b2-b0e2-4128-87ba-ae2311850f1f", "type": "concept", "title": "Landing pages, forms, calls, QR codes, SMS, email, and mail"}, {"id": "b6ee09b9-57d1-4cc9-8664-5710bb635118", "type": "concept", "title": "Response rate, conversion rate, cost per acquisition, and revenue per send"}], "description": "Students learn how direct marketing differs from broad awareness communication."}, {"id": "c98df5fb-3533-4c41-8626-4fe2d4bed0cd", "type": "subtopic", "title": "CRM and Customer Lifecycle", "children": [{"id": "13482736-1d1f-4eb9-9c2c-a23ad27a14f0", "type": "concept", "title": "Acquisition, onboarding, activation, retention, winback, loyalty, and referral"}, {"id": "37c0db84-afae-427a-b63d-36d22090be39", "type": "concept", "title": "Lifecycle triggers, journeys, and nurture flows"}, {"id": "5491cdd1-dcc7-43cd-882c-2586306c6473", "type": "concept", "title": "Customer lifetime value and customer equity"}], "description": "The purpose is to map communication to customer states and relationship value."}, {"id": "e9dc56d4-dd8f-45cb-ad0c-97e793a11071", "type": "subtopic", "title": "Marketing Automation", "children": [{"id": "284a8d13-acab-4b7a-94ec-ff6b49ea64b9", "type": "concept", "title": "Segmentation logic, lead scoring, workflows, suppression, and frequency caps"}, {"id": "d0c622ee-0ff7-4e26-9ee1-893cc0000661", "type": "concept", "title": "Testing subject lines, offers, timing, and creative modules"}, {"id": "06b6c5fe-4ff8-4928-921d-466b6e0552f9", "type": "concept", "title": "Deliverability, consent, preference centers, and data quality"}], "description": "Students learn how automation scales relevance while requiring governance and restraint."}]}, {"id": "f5fe7ef8-0409-4350-8e2d-9d26dcd24d2b", "type": "topic", "title": "Experiential Marketing, Events and Sponsorship", "description": "Experiences can make a brand tangible, social, and memorable. This section teaches how events and sponsorships become strategic communication platforms rather than isolated activations.", "children": [{"id": "d1283ff5-8756-42bc-8852-619b9d74166b", "type": "subtopic", "title": "Experience Strategy", "children": [{"id": "eb06ca40-9aaa-43ff-ac02-5184982b9ec4", "type": "concept", "title": "Event objectives, audience journey, invitation, experience, follow-up"}, {"id": "995514a7-1eb8-4bf7-a0e0-a42dff3fa571", "type": "concept", "title": "Pop-ups, demos, conferences, sampling, community events, and virtual experiences"}, {"id": "5d923498-98b2-4c2e-8af3-27d045f53911", "type": "concept", "title": "Brand immersion, participation, and memory creation"}], "description": "Students learn to design live, digital, and hybrid experiences around audience value and brand meaning."}, {"id": "a7043609-3685-47b8-bbe4-13a7a00a0b6c", "type": "subtopic", "title": "Sponsorship and Partnerships", "children": [{"id": "3d6f1074-8791-483b-a7a7-041086ab333c", "type": "concept", "title": "Rights, assets, fit, activation plans, and exclusivity"}, {"id": "85ec3f2f-80d4-430d-9900-9de2410e25ba", "type": "concept", "title": "Sports, entertainment, culture, nonprofit, and campus sponsorships"}, {"id": "4abcdc8d-ba5b-4372-919e-699c8e344a04", "type": "concept", "title": "Co-marketing, partner governance, and value exchange"}], "description": "The focus is on aligning with properties, creators, organizations, or causes that transfer meaning to the brand."}, {"id": "75ac4dcb-b5f1-460f-a100-d6ae488840b5", "type": "subtopic", "title": "Measurement and Operations", "children": [{"id": "5508ad02-9200-4fe6-91ab-b084b42af7f4", "type": "concept", "title": "Attendance, leads, engagement, sentiment, sales lift, and media value"}, {"id": "bd301b8c-ab33-4900-9eca-40d8b09e5214", "type": "concept", "title": "Run-of-show, staffing, vendors, permits, logistics, and risk planning"}, {"id": "30199ef0-864d-455e-91b5-49d94565082c", "type": "concept", "title": "Post-event content, retargeting, and CRM integration"}], "description": "Students learn the practical discipline needed to prove value and execute well."}]}, {"id": "1d7b6506-d268-4c89-ad71-5bcd9498e841", "type": "topic", "title": "Influencer, Creator and Partnership Strategy", "description": "Creators and partners can provide credibility, cultural fluency, and distribution, but they also introduce brand safety and governance challenges. This unit teaches responsible creator-led IMC.", "children": [{"id": "eadbc4ca-c5db-4d97-8ed2-58e39e5e23a7", "type": "subtopic", "title": "Creator Fit and Selection", "children": [{"id": "ac39cd26-eb91-46b2-b5f5-8f4a3513e0d1", "type": "concept", "title": "Audience demographics, engagement quality, content fit, and credibility"}, {"id": "68c86f30-a84f-4b88-8103-ad2def7c7647", "type": "concept", "title": "Macro, mid-tier, micro, nano, expert, employee, and customer advocates"}, {"id": "c27f093e-7276-4554-9c8d-8d6a40291dcd", "type": "concept", "title": "Brand safety, past content review, and reputational risk"}], "description": "Students learn how to choose partners based on audience, trust, relevance, and brand alignment."}, {"id": "f7beae3d-a327-41ca-8b80-f959e4d921f0", "type": "subtopic", "title": "Collaboration and Content Governance", "children": [{"id": "bea3f563-883f-4fa1-91f6-3fe86cab6a89", "type": "concept", "title": "Briefs, creative freedom, approvals, usage rights, and exclusivity"}, {"id": "ca59ae46-cefb-4b55-8940-911a8f18a613", "type": "concept", "title": "Disclosure requirements, FTC guidance, and sponsored content clarity"}, {"id": "9e9037b3-340b-4a5f-a3ce-d1d18f40bf66", "type": "concept", "title": "Asset rights, whitelisting, boosting, and paid amplification"}], "description": "The goal is to balance creator authenticity with campaign strategy and compliance."}, {"id": "9faed263-303b-43e8-b49d-9a12dcb6ad10", "type": "subtopic", "title": "Creator Measurement", "children": [{"id": "48047384-602c-4671-ad84-7ff10e8696be", "type": "concept", "title": "Reach, engagement, click-through, conversion, lift, sentiment, and content reuse value"}, {"id": "49acaa3f-2faa-402f-a8c5-47ea116b2572", "type": "concept", "title": "Promo codes, UTM links, affiliate tracking, and incrementality tests"}, {"id": "647e65a2-946f-4720-b15f-5dd78f5164cb", "type": "concept", "title": "Learning across creator cohorts and formats"}], "description": "Students learn to assess creator work beyond vanity metrics."}]}, {"id": "e4489dcd-df40-4195-9200-a06bc54f9445", "type": "topic", "title": "Analytics, Attribution and Marketing ROI", "description": "World-class IMC treats measurement as a learning system, not a final report. This unit builds fluency in campaign metrics, dashboards, experiments, attribution, and ROI judgment.", "children": [{"id": "419a69f4-49fe-48d5-8e1f-5788d9f6b9a4", "type": "subtopic", "title": "Measurement Planning", "children": [{"id": "020853af-cc15-47c4-b0ec-b591f0ed214d", "type": "concept", "title": "Objectives, KPIs, targets, benchmarks, and decision rules"}, {"id": "839dffb6-c14e-475a-8c7f-26483d9909ae", "type": "concept", "title": "Input, output, outcome, and business-impact metrics"}, {"id": "0755e4d0-d907-4d91-af46-152029385310", "type": "concept", "title": "Measurement briefs, tagging plans, and dashboard design"}], "description": "Students learn to define success before launch so every tactic has a measurement role."}, {"id": "dbace122-1d80-4dfa-a4cc-8fa73fc85d19", "type": "subtopic", "title": "Attribution and Incrementality", "children": [{"id": "d630ba90-1d6d-4f55-9d84-48b20e317388", "type": "concept", "title": "Last-click, multi-touch, marketing mix modeling, geo tests, holdouts, and lift studies"}, {"id": "26581fc9-cf35-47e5-9f77-16cbfb37308e", "type": "concept", "title": "Correlation versus causation and common attribution bias"}, {"id": "33856856-deeb-42af-8d1f-dae51c11b3f7", "type": "concept", "title": "Privacy changes, cookie loss, walled gardens, and modeled conversions"}], "description": "The point is to understand what can and cannot be claimed from campaign data."}, {"id": "f75579b5-ac33-4593-b4bc-195def4f8bf3", "type": "subtopic", "title": "ROI and Learning Loops", "children": [{"id": "74912103-a45e-4928-b6d4-87a0c8a51f2b", "type": "concept", "title": "ROI, ROAS, CAC, LTV, payback, marginal return, and diminishing returns"}, {"id": "d089feb0-4997-42ae-bd7e-4826c34750cf", "type": "concept", "title": "Creative, audience, offer, channel, and landing page diagnostics"}, {"id": "de397093-8f26-4dcc-a933-c4eae9b46f3a", "type": "concept", "title": "Post-campaign analysis, recommendations, and knowledge management"}], "description": "Students learn how to interpret performance in a way that improves future strategy."}]}, {"id": "23ac4bc1-98bc-41aa-afab-cdcf2ae069d0", "type": "topic", "title": "Budgeting, Forecasting and Resource Allocation", "description": "IMC decisions are constrained by budget, time, talent, and risk. This section teaches students how to allocate resources with financial discipline and strategic intent.", "children": [{"id": "549d4a3c-0b9f-4434-80c4-e6f5c2493902", "type": "subtopic", "title": "Budgeting Methods", "children": [{"id": "467128f9-a224-40f5-893a-51587f438dcf", "type": "concept", "title": "Objective-and-task, percentage-of-sales, competitive parity, affordability, and experimental budgets"}, {"id": "e1782f09-1c9c-4654-bd7c-e9071a4d6727", "type": "concept", "title": "Working versus non-working media costs"}, {"id": "28ae84b1-f52b-4d72-932b-9c6c641c5812", "type": "concept", "title": "Production, agency, technology, talent, research, and contingency costs"}], "description": "Students learn common ways organizations set communication budgets and the trade-offs each creates."}, {"id": "bf58c301-069b-4960-ac72-2798debe3222", "type": "subtopic", "title": "Forecasting Campaign Results", "children": [{"id": "fff45461-5f8f-4f0e-84f4-70571506731f", "type": "concept", "title": "Reach, response, conversion, revenue, margin, and lifetime value assumptions"}, {"id": "97aeced0-af60-490d-98a2-bced21c11613", "type": "concept", "title": "Scenario planning and sensitivity analysis"}, {"id": "9781f85e-0c3f-49d7-b86d-826905ee62d5", "type": "concept", "title": "Expected value and risk-adjusted campaign choices"}], "description": "The aim is to make campaign plans testable before money is committed."}, {"id": "48f1c5d4-11b6-4eac-8614-03fe8e2df0b1", "type": "subtopic", "title": "Resource Allocation", "children": [{"id": "a15712d4-cc8c-4ead-81d0-ff750fb16a14", "type": "concept", "title": "Portfolio balance between brand and performance"}, {"id": "d869f288-fe9d-4ad7-af3a-6bf4d18b6dbe", "type": "concept", "title": "Marginal return, saturation, and budget reallocation"}, {"id": "7714aa98-0ff7-43ed-89c5-3eec4b365275", "type": "concept", "title": "Governance for mid-campaign optimization"}], "description": "Students learn to distribute spend across audiences, channels, creative, and time."}]}, {"id": "c59d4550-9c57-4c9b-a5db-2faf57ef61e8", "type": "topic", "title": "Legal, Ethical, Privacy and Inclusive Communication", "description": "IMC operates in a trust environment shaped by law, platform policy, data use, representation, and social responsibility. This section makes ethical judgment part of campaign quality.", "children": [{"id": "52112339-05f9-4f1e-9922-3d5c7a091675", "type": "subtopic", "title": "Advertising Law and Claims", "children": [{"id": "25c4224f-b9f5-4f1b-a52e-c6ca8c8ff26d", "type": "concept", "title": "Claim substantiation, comparative advertising, endorsements, disclosures, and native advertising"}, {"id": "d84507e0-88c2-432a-9f25-29871ca96127", "type": "concept", "title": "FTC, platform policies, industry self-regulation, and brand review processes"}, {"id": "bd74a3bf-2ab0-4aed-b906-d4afd5be2333", "type": "concept", "title": "Regulated categories and high-risk claims"}], "description": "Students learn the basic guardrails for truthful, substantiated, and non-deceptive communication."}, {"id": "94b8510e-0d05-48d5-85ca-0f2efb26c86c", "type": "subtopic", "title": "Privacy and Responsible Personalization", "children": [{"id": "26a49abb-2d72-466d-8736-1d1e37018923", "type": "concept", "title": "Consent, preference management, data minimization, security, and retention"}, {"id": "688c916a-d45a-47f6-be49-67e5c8ef05bd", "type": "concept", "title": "Sensitive data, vulnerable audiences, children, and health/financial inferences"}, {"id": "55b95c70-fa92-40b2-8148-0985f44a34e8", "type": "concept", "title": "Measurement loss, clean rooms, and privacy-preserving analytics"}], "description": "The point is to use data in ways that preserve consent, dignity, and trust."}, {"id": "565d39e7-9c7d-4383-926d-1e91f6b136b0", "type": "subtopic", "title": "Inclusive and Ethical Communication", "children": [{"id": "c23a8e11-8272-4329-b0fb-fdaec8759e53", "type": "concept", "title": "Stereotypes, cultural appropriation, tokenism, and bias in targeting"}, {"id": "7458b043-e890-442f-bc76-380438079dfa", "type": "concept", "title": "Accessibility in copy, visuals, video, color, captions, and UX"}, {"id": "673dd665-d3c4-435f-aec0-e154cbc47aee", "type": "concept", "title": "Sustainability, social claims, and avoiding purpose-washing"}], "description": "Students learn to evaluate representation, accessibility, and social impact with rigor."}]}, {"id": "651ec6ee-4915-4081-8a11-790c347292b5", "type": "topic", "title": "Campaign Operations, Agency Collaboration and Client Presentation", "description": "Excellent strategy must survive real execution. This unit teaches the workflow, collaboration, presentation, and decision skills that make IMC campaigns operationally credible.", "children": [{"id": "ed3e1d5a-7db5-4e01-b3dd-732181256ba8", "type": "subtopic", "title": "Campaign Workflow", "children": [{"id": "198485c2-cf47-46d0-8050-ec7da781ad4a", "type": "concept", "title": "Schedules, milestones, status systems, review rounds, and launch checklists"}, {"id": "c5750d08-7ca8-4024-96e9-83f5166139f0", "type": "concept", "title": "Creative, media, PR, legal, analytics, sales, and product coordination"}, {"id": "b1079e9a-a6db-465b-b759-559f3b65e54b", "type": "concept", "title": "Asset trafficking, QA, naming conventions, and handoff discipline"}], "description": "Students learn how campaign work moves from brief to launch to optimization to post-analysis."}, {"id": "8dd9069a-f568-47f0-ae74-74915dce7762", "type": "subtopic", "title": "Agency and Vendor Collaboration", "children": [{"id": "01840645-0652-4d82-952d-0a654dbac313", "type": "concept", "title": "Scopes of work, deliverables, roles, fees, timelines, and change management"}, {"id": "22c36ff5-288a-4333-b3f6-508ffe276851", "type": "concept", "title": "Briefings, feedback protocols, approvals, and accountability"}, {"id": "505e870a-8dae-4d1f-8101-17feab5798b6", "type": "concept", "title": "Procurement, rights, confidentiality, and performance review"}], "description": "The focus is on working professionally with agencies, freelancers, media partners, and internal teams."}, {"id": "91475e3e-e52d-450f-a71d-a1e8084adcdb", "type": "subtopic", "title": "Client and Executive Presentation", "children": [{"id": "307e3ce7-a8c6-49c4-b69d-64fdd9a9e36c", "type": "concept", "title": "Narrative structure, strategic rationale, evidence, and trade-offs"}, {"id": "f6e5edbc-ca86-4807-afc3-1199a65d386b", "type": "concept", "title": "Visualizing plans, budgets, journey maps, and dashboards"}, {"id": "52cfef63-941b-427e-b05e-08456db23832", "type": "concept", "title": "Handling objections, defending assumptions, and documenting decisions"}], "description": "Students learn to make campaign recommendations clear, persuasive, and decision-ready."}]}, {"id": "1269c111-a7e1-49db-8c65-bd30a02e8758", "type": "topic", "title": "Capstone Integrated Campaign Plan", "description": "The course culminates in a professional integrated campaign plan. Students synthesize research, strategy, creative, media, PR, digital, budget, measurement, ethics, and presentation into one coherent recommendation.", "children": [{"id": "ddb82b2e-f6dd-48cf-8746-87a2b9cfc9bf", "type": "subtopic", "title": "Campaign Diagnosis and Brief", "children": [{"id": "102178be-1e20-40fd-8f72-8aaaf288e308", "type": "concept", "title": "Situation analysis, brand audit, customer insight, competitor review, and opportunity definition"}, {"id": "9c9f8038-6d0f-41ef-81c1-f0c8bfe06e95", "type": "concept", "title": "Campaign objective, target audience, positioning, and key message"}, {"id": "4d27f3f0-a6e1-48ed-962f-6852b7209e16", "type": "concept", "title": "Success metrics, constraints, assumptions, and risks"}], "description": "Students begin by identifying the marketing problem and translating it into a strong IMC brief."}, {"id": "bb2bb652-8d5a-450a-8b45-b70c0af23ca4", "type": "subtopic", "title": "Integrated Plan Development", "children": [{"id": "d09ae7a0-4ae7-4e65-84cc-a72d6d483a81", "type": "concept", "title": "Creative platform, message map, channel mix, media calendar, PR plan, content system, CRM flow, and activation plan"}, {"id": "8fda658f-3aef-4d8b-8aaa-fc2d7b5b1798", "type": "concept", "title": "Budget allocation, production plan, staffing, and timeline"}, {"id": "2afd0269-161f-4be5-9171-562fb92f8a65", "type": "concept", "title": "Legal, ethical, accessibility, privacy, and inclusion review"}], "description": "The capstone requires students to design a coordinated campaign across channels and moments."}, {"id": "4c2acaaa-1de3-4ec2-86d3-24b88454990e", "type": "subtopic", "title": "Pitch, Measurement and Reflection", "children": [{"id": "2cf05071-7845-4da3-a4ce-8a089320a28c", "type": "concept", "title": "Executive pitch deck, campaign rationale, and decision asks"}, {"id": "272d68db-5110-4020-803d-6dd7883e26e4", "type": "concept", "title": "Dashboard mockup, attribution plan, experiment design, and ROI forecast"}, {"id": "db73d96f-b2c3-4670-8d24-4b6ac9072f70", "type": "concept", "title": "Post-pitch critique, revisions, and individual learning memo"}], "description": "Students finish by presenting the campaign and explaining how it will be evaluated and improved."}]}], "dbBacked": true}$imcjson$::jsonb,
