insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('731f90e1-bbee-499e-b837-8d8c235f21a3', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'IMC Strategy and Campaign Architecture', 'This opening unit frames IMC as a disciplined system for aligning brand, audience, message, channel, and measurement. Students learn to turn business goals into coordinated communication choices rather than isolated tactics.', 0),
  ('def39c07-c172-4e12-95aa-85a72a58b347', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '731f90e1-bbee-499e-b837-8d8c235f21a3', 'subtopic'::public.curated_course_node_type, 'Strategic Role of IMC', 'The goal is to understand why integrated communications matter: they reduce message fragmentation and make every customer touchpoint reinforce a coherent market position.', 0),
  ('c9ad6f37-20b5-45a9-bccb-a8a311f19e2b', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'def39c07-c172-4e12-95aa-85a72a58b347', 'concept'::public.curated_course_node_type, 'Business goals, communication goals, and behavioral objectives', null, 0),
  ('21d88f55-9695-4f2d-bd5d-296864bd20b0', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'def39c07-c172-4e12-95aa-85a72a58b347', 'concept'::public.curated_course_node_type, 'Brand consistency across paid, owned, earned, shared, and retail channels', null, 1),
  ('2c53d32a-be8c-48be-a92a-98598f911935', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'def39c07-c172-4e12-95aa-85a72a58b347', 'concept'::public.curated_course_node_type, 'Integration across advertising, PR, direct, sales, social, content, and events', null, 2),
  ('4cfd7709-a9b6-459b-badd-eb7beec2feb8', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '731f90e1-bbee-499e-b837-8d8c235f21a3', 'subtopic'::public.curated_course_node_type, 'Campaign Planning Models', 'Students learn practical planning models that convert ambiguity into an organized campaign logic.', 1),
  ('4ec84146-2003-4b40-9975-330bfd80e9a2', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '4cfd7709-a9b6-459b-badd-eb7beec2feb8', 'concept'::public.curated_course_node_type, 'Situation analysis, audience insight, objectives, strategy, tactics, action, control', null, 0),
  ('ce156cfa-942f-44f1-b5e6-2367819d0e92', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '4cfd7709-a9b6-459b-badd-eb7beec2feb8', 'concept'::public.curated_course_node_type, 'Brief-to-execution workflow and approval gates', null, 1),
  ('e5ec1b60-52c8-4f4d-9825-88f419965658', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '4cfd7709-a9b6-459b-badd-eb7beec2feb8', 'concept'::public.curated_course_node_type, 'Campaign maps that connect message, channel, timing, and measurement', null, 2),
  ('31e88dce-5569-4b57-81f3-2f25ead47497', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '731f90e1-bbee-499e-b837-8d8c235f21a3', 'subtopic'::public.curated_course_node_type, 'Professional IMC Standards', 'This subtopic sets the bar for professional campaign thinking in top marketing programs and agencies.', 2),
  ('adec8e0e-0208-4b06-88aa-16d639461c70', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '31e88dce-5569-4b57-81f3-2f25ead47497', 'concept'::public.curated_course_node_type, 'Evidence-based strategy rather than channel-first execution', null, 0),
  ('ce379ae1-09ec-4df1-9cfa-a1e988ba471d', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '31e88dce-5569-4b57-81f3-2f25ead47497', 'concept'::public.curated_course_node_type, 'Cross-functional collaboration among brand, media, analytics, product, and sales', null, 1),
  ('9440eb71-ade1-499b-9d24-7e2822a9c3af', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '31e88dce-5569-4b57-81f3-2f25ead47497', 'concept'::public.curated_course_node_type, 'Portfolio thinking across short-term activation and long-term brand building', null, 2),
  ('802fa105-53c0-4c5c-b6c7-80afd68df0df', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'Customer Insight, Segmentation, Targeting and Positioning', 'IMC becomes powerful when it is grounded in a precise view of customers and the market. This section develops the insight work behind who the campaign serves and what distinctive meaning it should own.', 1),
  ('d62b5a6e-ee50-412d-9048-1da1b6477010', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '802fa105-53c0-4c5c-b6c7-80afd68df0df', 'subtopic'::public.curated_course_node_type, 'Customer and Market Insight', 'Students learn to move from demographic description to sharper human, behavioral, cultural, and category insight.', 0),
  ('102533dd-6747-4df9-9450-a45822d88d85', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'd62b5a6e-ee50-412d-9048-1da1b6477010', 'concept'::public.curated_course_node_type, 'Jobs-to-be-done, motivations, barriers, and triggers', null, 0),
  ('aca564c9-23ab-4c96-9cac-3b3c8ddad22c', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'd62b5a6e-ee50-412d-9048-1da1b6477010', 'concept'::public.curated_course_node_type, 'Category entry points and moments of need', null, 1),
  ('9acb4552-4a25-4128-9220-1f94665201f4', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'd62b5a6e-ee50-412d-9048-1da1b6477010', 'concept'::public.curated_course_node_type, 'Voice-of-customer, social listening, search behavior, and review mining', null, 2),
  ('3396ce21-73c0-40b6-9d79-365a64461efe', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '802fa105-53c0-4c5c-b6c7-80afd68df0df', 'subtopic'::public.curated_course_node_type, 'Segmentation and Targeting', 'The purpose is to choose valuable audiences deliberately instead of trying to speak to everyone at once.', 1),
  ('10d4346a-f9e3-4bad-890b-b550e14f7a4f', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '3396ce21-73c0-40b6-9d79-365a64461efe', 'concept'::public.curated_course_node_type, 'Behavioral, psychographic, firmographic, and value-based segmentation', null, 0),
  ('515ff48a-23e6-4184-bd53-410009f6e04e', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '3396ce21-73c0-40b6-9d79-365a64461efe', 'concept'::public.curated_course_node_type, 'Target attractiveness, accessibility, and strategic fit', null, 1),
  ('c002b902-fb0a-4d2a-8d14-b1b119668993', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '3396ce21-73c0-40b6-9d79-365a64461efe', 'concept'::public.curated_course_node_type, 'Primary, secondary, influencer, and internal stakeholder audiences', null, 2),
  ('d9cc0c33-3995-4522-8188-eafa2cb46809', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '802fa105-53c0-4c5c-b6c7-80afd68df0df', 'subtopic'::public.curated_course_node_type, 'Positioning and Value Proposition', 'Students learn how a campaign should sharpen what the brand means and why that meaning matters.', 2),
  ('41a63e76-e3e9-4266-b915-24f1bebc94df', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'd9cc0c33-3995-4522-8188-eafa2cb46809', 'concept'::public.curated_course_node_type, 'Points of parity and points of difference', null, 0),
  ('3ecc864b-cdd3-4acb-bcac-e0f2672f5821', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'd9cc0c33-3995-4522-8188-eafa2cb46809', 'concept'::public.curated_course_node_type, 'Positioning statements and value propositions', null, 1),
  ('60c79ef9-fe2b-445c-bab7-2bf7547b0f3a', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'd9cc0c33-3995-4522-8188-eafa2cb46809', 'concept'::public.curated_course_node_type, 'Competitor mapping, perceptual maps, and white-space analysis', null, 2),
  ('689bcfc4-f770-4e67-a350-14ee942af06b', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'Brand Identity, Equity and Message Consistency', 'Integrated communications must protect and grow brand equity. This unit connects visual identity, verbal identity, positioning, memory structures, and trust.', 2),
  ('fb824f76-c470-42d2-b7d4-430ae1a4defa', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '689bcfc4-f770-4e67-a350-14ee942af06b', 'subtopic'::public.curated_course_node_type, 'Brand Identity Systems', 'Students learn the elements that make a brand recognizable and usable across every channel.', 0),
  ('c2eb4989-1aeb-455c-ab41-f1ceb3fbdb09', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'fb824f76-c470-42d2-b7d4-430ae1a4defa', 'concept'::public.curated_course_node_type, 'Name, logo, color, typography, voice, tone, and sonic cues', null, 0),
  ('a6b4338c-1fab-4462-ac31-92beae42f7cb', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'fb824f76-c470-42d2-b7d4-430ae1a4defa', 'concept'::public.curated_course_node_type, 'Brand guidelines, governance, and approval systems', null, 1),
  ('a1c50d8a-e44f-48d7-954c-bee8834b480f', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'fb824f76-c470-42d2-b7d4-430ae1a4defa', 'concept'::public.curated_course_node_type, 'Adaptation across formats without losing coherence', null, 2),
  ('ec895059-cf8e-425d-92b5-c5388f0eeeb1', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '689bcfc4-f770-4e67-a350-14ee942af06b', 'subtopic'::public.curated_course_node_type, 'Brand Equity and Mental Availability', 'The gist is that communication builds memory, salience, associations, and preference over time.', 1),
  ('8fc4f80d-5b36-443c-b43b-babdbdb4ea70', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ec895059-cf8e-425d-92b5-c5388f0eeeb1', 'concept'::public.curated_course_node_type, 'Awareness, associations, perceived quality, loyalty, and differentiation', null, 0),
  ('4676de5a-e391-48a2-b96a-809f0259b0cf', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ec895059-cf8e-425d-92b5-c5388f0eeeb1', 'concept'::public.curated_course_node_type, 'Distinctive brand assets and category cues', null, 1),
  ('d5254ab8-ebab-45f9-a48e-cdc60daf1893', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ec895059-cf8e-425d-92b5-c5388f0eeeb1', 'concept'::public.curated_course_node_type, 'Long-term brand building versus short-term conversion', null, 2),
  ('84d06fdc-012b-4b90-af32-7c0c12bd8649', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '689bcfc4-f770-4e67-a350-14ee942af06b', 'subtopic'::public.curated_course_node_type, 'Message Consistency and Variation', 'Students learn to distinguish strategic consistency from repetitive sameness.', 2),
  ('31da60d4-8123-48c8-b2ec-584d19e36842', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '84d06fdc-012b-4b90-af32-7c0c12bd8649', 'concept'::public.curated_course_node_type, 'Message hierarchy and proof architecture', null, 0),
  ('d5519d12-3bb5-4a47-b7e2-65337e6a247f', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '84d06fdc-012b-4b90-af32-7c0c12bd8649', 'concept'::public.curated_course_node_type, 'Core claims, reasons to believe, and supporting evidence', null, 1),
  ('d032c4db-5d22-4cbe-ae81-caa3555d48cc', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '84d06fdc-012b-4b90-af32-7c0c12bd8649', 'concept'::public.curated_course_node_type, 'Audience, channel, and funnel adaptations', null, 2),
  ('cc00ca58-4faf-42ab-9bb3-14149ba2693b', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'The Creative Brief and Big Idea', 'A strong brief is the bridge between strategy and creative work. This section teaches students how to express the problem, audience, promise, evidence, tone, and constraints in a way that unlocks great execution.', 3);
