  ('d2a71148-e94b-433f-b08d-1f0d46428302', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'cc00ca58-4faf-42ab-9bb3-14149ba2693b', 'subtopic'::public.curated_course_node_type, 'Creative Brief Foundations', 'Students learn what a brief must contain and why vague briefs lead to weak campaigns.', 0),
