  ('ffb49a27-d7fd-4936-97c3-95adb9104646', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '089d6e6b-0afe-4dfe-ad10-8a2b232bf10f', 'concept'::public.curated_course_node_type, 'Central campaign thought and strategic hook', null, 0),
