  ('460bd16b-0d70-4e8f-aa8c-fc7d80eb55e0', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '089d6e6b-0afe-4dfe-ad10-8a2b232bf10f', 'concept'::public.curated_course_node_type, 'Distinctiveness, emotional resonance, usefulness, and shareability', null, 2),
  ('bcad289d-b976-456b-b581-4515468e59b4', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'cc00ca58-4faf-42ab-9bb3-14149ba2693b', 'subtopic'::public.curated_course_node_type, 'Creative Review and Feedback', 'Students learn how to critique creative work against strategy instead of personal taste.', 2),
  ('768eddbc-3352-4f1e-8f5c-c74b2490eb32', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'bcad289d-b976-456b-b581-4515468e59b4', 'concept'::public.curated_course_node_type, 'Feedback language for message, brand fit, clarity, originality, and feasibility', null, 0),
  ('206bdaec-9b11-4191-860d-48f820754792', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'bcad289d-b976-456b-b581-4515468e59b4', 'concept'::public.curated_course_node_type, 'Iteration cycles from thumbnails to scripts to prototypes', null, 1),
  ('dbc2b80a-057c-4010-a094-2f0348266920', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'bcad289d-b976-456b-b581-4515468e59b4', 'concept'::public.curated_course_node_type, 'Avoiding committee dilution and preserving strategic intent', null, 2),
  ('ef25ff45-e634-45b2-bc32-856cdee07d97', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'Advertising Strategy and Persuasive Communication', 'Advertising remains a central IMC tool because it can shape awareness, memory, emotion, and demand at scale. This unit connects persuasion theory with practical campaign design.', 4),
