  ('2d53577a-d795-4309-b1e5-2bf8ee19f524', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ad199b64-9fd4-4ea6-828e-3b8d668d9400', 'concept'::public.curated_course_node_type, 'Ethos, pathos, logos, social proof, scarcity, authority, and reciprocity', null, 0),
  ('1cbfaf39-3bb0-4483-9cef-a68f606f1014', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ad199b64-9fd4-4ea6-828e-3b8d668d9400', 'concept'::public.curated_course_node_type, 'Elaboration likelihood, framing, priming, and fluency', null, 1),
  ('1f2c8d9e-8f93-4551-b9f4-98311c89ddf2', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ad199b64-9fd4-4ea6-828e-3b8d668d9400', 'concept'::public.curated_course_node_type, 'Rational, emotional, transformational, comparative, and reminder appeals', null, 2),
  ('242d1dd6-9c12-4a66-877b-304890186a2d', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ef25ff45-e634-45b2-bc32-856cdee07d97', 'subtopic'::public.curated_course_node_type, 'Advertising Objectives', 'The point is to choose the right advertising job before choosing the advertisement.', 1),
  ('b12cc067-6778-4b7c-a7e4-75d703f5eadd', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '242d1dd6-9c12-4a66-877b-304890186a2d', 'concept'::public.curated_course_node_type, 'Awareness, consideration, preference, trial, repeat purchase, loyalty, and advocacy', null, 0),
  ('25ade7ec-0379-4c51-a339-e9c4fbe1b164', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '242d1dd6-9c12-4a66-877b-304890186a2d', 'concept'::public.curated_course_node_type, 'Category creation, repositioning, launch, defense, and growth objectives', null, 1),
