  ('af33520a-414a-4aa6-b5c3-9382c4dc49e3', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ef25ff45-e634-45b2-bc32-856cdee07d97', 'subtopic'::public.curated_course_node_type, 'Executional Formats', 'Students learn the craft options that turn strategy into attention-worthy communication.', 2),
  ('b98d88a0-0d97-4df9-92f0-3ffdc373655c', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'af33520a-414a-4aa6-b5c3-9382c4dc49e3', 'concept'::public.curated_course_node_type, 'Demonstration, testimonial, slice-of-life, problem-solution, story, humor, and comparison', null, 0),
