  ('6ad2382b-97e6-4bd1-ae85-553f5144f64e', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'af33520a-414a-4aa6-b5c3-9382c4dc49e3', 'concept'::public.curated_course_node_type, 'Claims support, substantiation, and responsible persuasion', null, 2),
