  ('560ef1a5-114d-44ae-a075-d536cdead579', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '925c3b4b-e3e9-4b9f-8d13-a951786a0a78', 'subtopic'::public.curated_course_node_type, 'Copywriting for Campaigns', 'Students learn how words move from headline to call-to-action while carrying the brand''s voice.', 0),
  ('ea45f5d0-e764-40b1-a901-76c4d5160af9', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '560ef1a5-114d-44ae-a075-d536cdead579', 'concept'::public.curated_course_node_type, 'Headlines, taglines, body copy, captions, scripts, subject lines, and CTAs', null, 0),
  ('12cc6a13-9f52-42c3-873a-2e4dab156bd5', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '560ef1a5-114d-44ae-a075-d536cdead579', 'concept'::public.curated_course_node_type, 'Clarity, brevity, specificity, rhythm, and tone', null, 1),
  ('d0ceaa56-96e3-4bbb-9c3f-1c83c3613578', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '560ef1a5-114d-44ae-a075-d536cdead579', 'concept'::public.curated_course_node_type, 'Writing for different funnel stages and formats', null, 2),
  ('cde562e4-2588-4a37-8024-36b30719dcc5', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '925c3b4b-e3e9-4b9f-8d13-a951786a0a78', 'subtopic'::public.curated_course_node_type, 'Art Direction and Visual Storytelling', 'The aim is to understand how design choices communicate before the audience reads a word.', 1),
  ('830f3fba-cd8e-4b28-9f0c-8fab4e040db4', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'cde562e4-2588-4a37-8024-36b30719dcc5', 'concept'::public.curated_course_node_type, 'Composition, hierarchy, color, imagery, typography, and motion cues', null, 0),
  ('4de1cac7-ec29-4c2c-8bc5-4f36b6af263c', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'cde562e4-2588-4a37-8024-36b30719dcc5', 'concept'::public.curated_course_node_type, 'Brand asset use across print, digital, video, and outdoor', null, 1),
  ('2169bff3-8ef3-4566-9c53-bfa0f9af7fda', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'cde562e4-2588-4a37-8024-36b30719dcc5', 'concept'::public.curated_course_node_type, 'Accessibility, legibility, and mobile-first visual design', null, 2),
  ('c9be6bac-7b00-4db7-a14f-5f51e5f6af68', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '925c3b4b-e3e9-4b9f-8d13-a951786a0a78', 'subtopic'::public.curated_course_node_type, 'Production and Adaptation', 'Students learn to manage creative work across formats, deadlines, budgets, and technical specs.', 2),
  ('76bf164a-8654-4c34-9537-3f98da0b1433', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'c9be6bac-7b00-4db7-a14f-5f51e5f6af68', 'concept'::public.curated_course_node_type, 'Asset matrices, deliverable lists, localization, and resizing', null, 0),
  ('12331290-9290-4881-8eca-57cf1302d6b2', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'c9be6bac-7b00-4db7-a14f-5f51e5f6af68', 'concept'::public.curated_course_node_type, 'Photography, video, motion, audio, and design production basics', null, 1),
  ('e550b009-d318-49cb-b603-1e500844fc02', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'c9be6bac-7b00-4db7-a14f-5f51e5f6af68', 'concept'::public.curated_course_node_type, 'Versioning for audiences, platforms, placements, and tests', null, 2),
  ('ad69ecc2-ded8-4396-85a7-a99e512e879d', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'Media Planning, Buying and Channel Mix', 'A great message fails if it reaches the wrong people in the wrong context. This unit teaches how media choices translate objectives into reach, frequency, impact, and efficiency.', 6),
  ('29bdcf22-8d34-44e3-bb4a-322d1848dad8', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ad69ecc2-ded8-4396-85a7-a99e512e879d', 'subtopic'::public.curated_course_node_type, 'Media Objectives and Metrics', 'Students learn the language of media planning so they can connect exposure to outcomes.', 0);
