  ('d39bfab4-78d7-4456-bea5-d765bc3674a6', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'eaf3f422-9b2d-455e-b2fc-141f7e94b239', 'concept'::public.curated_course_node_type, 'Programmatic, direct buys, sponsorships, and marketplace dynamics', null, 1),
  ('2940c0f0-f3d4-4061-8c78-69c43ffd2c44', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'eaf3f422-9b2d-455e-b2fc-141f7e94b239', 'concept'::public.curated_course_node_type, 'Budget pacing, bid strategy, creative rotation, and optimization rules', null, 2),
