  ('79fe921d-da5a-4193-9a71-52cfab83f0c9', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '9ee3d53e-ea53-4040-aef3-ad7ae3db502c', 'concept'::public.curated_course_node_type, 'Platform-native formats, algorithms, and attention patterns', null, 1),
  ('93a11944-069a-4335-9be4-7f15e0cb74f6', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '9ee3d53e-ea53-4040-aef3-ad7ae3db502c', 'concept'::public.curated_course_node_type, 'Organic, paid, and boosted distribution', null, 2),
  ('af8ae819-40c6-4e59-9ef7-ea054a5f15d6', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '0b2d0b81-ed05-4d58-9e01-3ba43ee5d4d6', 'subtopic'::public.curated_course_node_type, 'Content Systems', 'The point is to manage content as a strategic system rather than a calendar of disconnected posts.', 1),
