  ('25b74eb6-b45f-419d-afb6-ad731a482e78', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '6b76f004-aa67-431d-bd81-c71fb9468210', 'concept'::public.curated_course_node_type, 'Community management, response protocols, and moderation', null, 0),
  ('1efeca61-0d45-414e-b30f-7fef5ba13377', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '6b76f004-aa67-431d-bd81-c71fb9468210', 'concept'::public.curated_course_node_type, 'User-generated content, advocacy, and social proof', null, 1),
  ('b8597550-0a5b-45ae-ba03-a0bc7682d2e3', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '6b76f004-aa67-431d-bd81-c71fb9468210', 'concept'::public.curated_course_node_type, 'Listening, sentiment, cultural timing, and escalation', null, 2),
