  ('1874a55e-f10a-4939-89ad-3beb7a26ddf5', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ba41671d-343d-4631-9454-5fb33044b93a', 'concept'::public.curated_course_node_type, 'Employees, investors, regulators, communities, partners, and advocacy groups', null, 0),
