  ('d8fafe19-1e4a-404c-bd27-382beaacfd6e', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '82dc67cb-c482-43c1-a41e-4fcf8f8a3701', 'concept'::public.curated_course_node_type, 'Risk mapping, scenarios, holding statements, and escalation trees', null, 0),
  ('a7a76a1f-b530-40c3-bc4c-6b084ded1408', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '82dc67cb-c482-43c1-a41e-4fcf8f8a3701', 'concept'::public.curated_course_node_type, 'Apology, correction, transparency, and accountability', null, 1),
  ('3cb83dd0-0a19-4375-977c-c148612409b7', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '82dc67cb-c482-43c1-a41e-4fcf8f8a3701', 'concept'::public.curated_course_node_type, 'Monitoring, misinformation, and post-crisis learning', null, 2),
