  ('8b1afa6b-1956-446d-992a-93fb73e00bd0', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '588d0ec2-ea13-4eb3-b2f0-6ede27bec0ab', 'subtopic'::public.curated_course_node_type, 'Retail and Shopper Communication', 'Students learn how IMC appears at the point of choice, both in-store and online.', 2),
  ('faf30aaa-9a3a-479e-9b22-6fce5bf80911', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '8b1afa6b-1956-446d-992a-93fb73e00bd0', 'concept'::public.curated_course_node_type, 'Shelf, display, packaging, ecommerce product pages, and retail media', null, 0),
  ('683019ab-2d8a-4983-944b-12ccaa8d3741', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '8b1afa6b-1956-446d-992a-93fb73e00bd0', 'concept'::public.curated_course_node_type, 'Path-to-purchase, planogram context, and impulse behavior', null, 1),
  ('255a6c95-991a-4b0a-a3af-c7169507304f', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '8b1afa6b-1956-446d-992a-93fb73e00bd0', 'concept'::public.curated_course_node_type, 'Trade-offs among margin, volume, brand health, and retailer goals', null, 2),
  ('eb97f1c7-bf4b-4c5f-b799-b90aeb0cefbe', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'Direct Marketing, CRM and Lifecycle Communication', 'Direct and CRM channels let brands build relationships over time with measurable behavior. This unit teaches lifecycle thinking from first contact to loyalty and advocacy.', 10),
  ('7e0dea41-1551-41b9-8207-f7f2b8202590', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'eb97f1c7-bf4b-4c5f-b799-b90aeb0cefbe', 'subtopic'::public.curated_course_node_type, 'Direct Response Foundations', 'Students learn how direct marketing differs from broad awareness communication.', 0),
  ('1ebacd54-6333-427f-b70c-387f49d5a2c9', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '7e0dea41-1551-41b9-8207-f7f2b8202590', 'concept'::public.curated_course_node_type, 'Offers, lists, targeting, personalization, creative, timing, and response paths', null, 0),
  ('42dc09b2-b0e2-4128-87ba-ae2311850f1f', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '7e0dea41-1551-41b9-8207-f7f2b8202590', 'concept'::public.curated_course_node_type, 'Landing pages, forms, calls, QR codes, SMS, email, and mail', null, 1),
  ('b6ee09b9-57d1-4cc9-8664-5710bb635118', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '7e0dea41-1551-41b9-8207-f7f2b8202590', 'concept'::public.curated_course_node_type, 'Response rate, conversion rate, cost per acquisition, and revenue per send', null, 2),
  ('c98df5fb-3533-4c41-8626-4fe2d4bed0cd', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'eb97f1c7-bf4b-4c5f-b799-b90aeb0cefbe', 'subtopic'::public.curated_course_node_type, 'CRM and Customer Lifecycle', 'The purpose is to map communication to customer states and relationship value.', 1),
  ('13482736-1d1f-4eb9-9c2c-a23ad27a14f0', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'c98df5fb-3533-4c41-8626-4fe2d4bed0cd', 'concept'::public.curated_course_node_type, 'Acquisition, onboarding, activation, retention, winback, loyalty, and referral', null, 0),
  ('37c0db84-afae-427a-b63d-36d22090be39', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'c98df5fb-3533-4c41-8626-4fe2d4bed0cd', 'concept'::public.curated_course_node_type, 'Lifecycle triggers, journeys, and nurture flows', null, 1),
  ('5491cdd1-dcc7-43cd-882c-2586306c6473', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'c98df5fb-3533-4c41-8626-4fe2d4bed0cd', 'concept'::public.curated_course_node_type, 'Customer lifetime value and customer equity', null, 2),
  ('e9dc56d4-dd8f-45cb-ad0c-97e793a11071', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'eb97f1c7-bf4b-4c5f-b799-b90aeb0cefbe', 'subtopic'::public.curated_course_node_type, 'Marketing Automation', 'Students learn how automation scales relevance while requiring governance and restraint.', 2),
  ('284a8d13-acab-4b7a-94ec-ff6b49ea64b9', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'e9dc56d4-dd8f-45cb-ad0c-97e793a11071', 'concept'::public.curated_course_node_type, 'Segmentation logic, lead scoring, workflows, suppression, and frequency caps', null, 0),
  ('d0c622ee-0ff7-4e26-9ee1-893cc0000661', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'e9dc56d4-dd8f-45cb-ad0c-97e793a11071', 'concept'::public.curated_course_node_type, 'Testing subject lines, offers, timing, and creative modules', null, 1),
  ('06b6c5fe-4ff8-4928-921d-466b6e0552f9', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'e9dc56d4-dd8f-45cb-ad0c-97e793a11071', 'concept'::public.curated_course_node_type, 'Deliverability, consent, preference centers, and data quality', null, 2),
  ('f5fe7ef8-0409-4350-8e2d-9d26dcd24d2b', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'Experiential Marketing, Events and Sponsorship', 'Experiences can make a brand tangible, social, and memorable. This section teaches how events and sponsorships become strategic communication platforms rather than isolated activations.', 11),
  ('d1283ff5-8756-42bc-8852-619b9d74166b', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'f5fe7ef8-0409-4350-8e2d-9d26dcd24d2b', 'subtopic'::public.curated_course_node_type, 'Experience Strategy', 'Students learn to design live, digital, and hybrid experiences around audience value and brand meaning.', 0),
  ('eb06ca40-9aaa-43ff-ac02-5184982b9ec4', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'd1283ff5-8756-42bc-8852-619b9d74166b', 'concept'::public.curated_course_node_type, 'Event objectives, audience journey, invitation, experience, follow-up', null, 0),
  ('995514a7-1eb8-4bf7-a0e0-a42dff3fa571', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'd1283ff5-8756-42bc-8852-619b9d74166b', 'concept'::public.curated_course_node_type, 'Pop-ups, demos, conferences, sampling, community events, and virtual experiences', null, 1),
  ('5d923498-98b2-4c2e-8af3-27d045f53911', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'd1283ff5-8756-42bc-8852-619b9d74166b', 'concept'::public.curated_course_node_type, 'Brand immersion, participation, and memory creation', null, 2),
  ('a7043609-3685-47b8-bbe4-13a7a00a0b6c', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'f5fe7ef8-0409-4350-8e2d-9d26dcd24d2b', 'subtopic'::public.curated_course_node_type, 'Sponsorship and Partnerships', 'The focus is on aligning with properties, creators, organizations, or causes that transfer meaning to the brand.', 1),
  ('3d6f1074-8791-483b-a7a7-041086ab333c', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'a7043609-3685-47b8-bbe4-13a7a00a0b6c', 'concept'::public.curated_course_node_type, 'Rights, assets, fit, activation plans, and exclusivity', null, 0),
  ('85ec3f2f-80d4-430d-9900-9de2410e25ba', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'a7043609-3685-47b8-bbe4-13a7a00a0b6c', 'concept'::public.curated_course_node_type, 'Sports, entertainment, culture, nonprofit, and campus sponsorships', null, 1),
  ('4abcdc8d-ba5b-4372-919e-699c8e344a04', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'a7043609-3685-47b8-bbe4-13a7a00a0b6c', 'concept'::public.curated_course_node_type, 'Co-marketing, partner governance, and value exchange', null, 2),
  ('75ac4dcb-b5f1-460f-a100-d6ae488840b5', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'f5fe7ef8-0409-4350-8e2d-9d26dcd24d2b', 'subtopic'::public.curated_course_node_type, 'Measurement and Operations', 'Students learn the practical discipline needed to prove value and execute well.', 2),
  ('5508ad02-9200-4fe6-91ab-b084b42af7f4', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '75ac4dcb-b5f1-460f-a100-d6ae488840b5', 'concept'::public.curated_course_node_type, 'Attendance, leads, engagement, sentiment, sales lift, and media value', null, 0),
  ('bd301b8c-ab33-4900-9eca-40d8b09e5214', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '75ac4dcb-b5f1-460f-a100-d6ae488840b5', 'concept'::public.curated_course_node_type, 'Run-of-show, staffing, vendors, permits, logistics, and risk planning', null, 1),
  ('30199ef0-864d-455e-91b5-49d94565082c', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '75ac4dcb-b5f1-460f-a100-d6ae488840b5', 'concept'::public.curated_course_node_type, 'Post-event content, retargeting, and CRM integration', null, 2),
  ('1d7b6506-d268-4c89-ad71-5bcd9498e841', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'Influencer, Creator and Partnership Strategy', 'Creators and partners can provide credibility, cultural fluency, and distribution, but they also introduce brand safety and governance challenges. This unit teaches responsible creator-led IMC.', 12),
  ('eadbc4ca-c5db-4d97-8ed2-58e39e5e23a7', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '1d7b6506-d268-4c89-ad71-5bcd9498e841', 'subtopic'::public.curated_course_node_type, 'Creator Fit and Selection', 'Students learn how to choose partners based on audience, trust, relevance, and brand alignment.', 0),
  ('ac39cd26-eb91-46b2-b5f5-8f4a3513e0d1', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'eadbc4ca-c5db-4d97-8ed2-58e39e5e23a7', 'concept'::public.curated_course_node_type, 'Audience demographics, engagement quality, content fit, and credibility', null, 0),
  ('68c86f30-a84f-4b88-8103-ad2def7c7647', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'eadbc4ca-c5db-4d97-8ed2-58e39e5e23a7', 'concept'::public.curated_course_node_type, 'Macro, mid-tier, micro, nano, expert, employee, and customer advocates', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('c27f093e-7276-4554-9c8d-8d6a40291dcd', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'eadbc4ca-c5db-4d97-8ed2-58e39e5e23a7', 'concept'::public.curated_course_node_type, 'Brand safety, past content review, and reputational risk', null, 2),
  ('f7beae3d-a327-41ca-8b80-f959e4d921f0', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '1d7b6506-d268-4c89-ad71-5bcd9498e841', 'subtopic'::public.curated_course_node_type, 'Collaboration and Content Governance', 'The goal is to balance creator authenticity with campaign strategy and compliance.', 1),
  ('bea3f563-883f-4fa1-91f6-3fe86cab6a89', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'f7beae3d-a327-41ca-8b80-f959e4d921f0', 'concept'::public.curated_course_node_type, 'Briefs, creative freedom, approvals, usage rights, and exclusivity', null, 0),
  ('ca59ae46-cefb-4b55-8940-911a8f18a613', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'f7beae3d-a327-41ca-8b80-f959e4d921f0', 'concept'::public.curated_course_node_type, 'Disclosure requirements, FTC guidance, and sponsored content clarity', null, 1),
  ('9e9037b3-340b-4a5f-a3ce-d1d18f40bf66', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'f7beae3d-a327-41ca-8b80-f959e4d921f0', 'concept'::public.curated_course_node_type, 'Asset rights, whitelisting, boosting, and paid amplification', null, 2),
  ('9faed263-303b-43e8-b49d-9a12dcb6ad10', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '1d7b6506-d268-4c89-ad71-5bcd9498e841', 'subtopic'::public.curated_course_node_type, 'Creator Measurement', 'Students learn to assess creator work beyond vanity metrics.', 2),
  ('48047384-602c-4671-ad84-7ff10e8696be', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '9faed263-303b-43e8-b49d-9a12dcb6ad10', 'concept'::public.curated_course_node_type, 'Reach, engagement, click-through, conversion, lift, sentiment, and content reuse value', null, 0),
  ('49acaa3f-2faa-402f-a8c5-47ea116b2572', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '9faed263-303b-43e8-b49d-9a12dcb6ad10', 'concept'::public.curated_course_node_type, 'Promo codes, UTM links, affiliate tracking, and incrementality tests', null, 1),
  ('647e65a2-946f-4720-b15f-5dd78f5164cb', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '9faed263-303b-43e8-b49d-9a12dcb6ad10', 'concept'::public.curated_course_node_type, 'Learning across creator cohorts and formats', null, 2),
  ('e4489dcd-df40-4195-9200-a06bc54f9445', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'Analytics, Attribution and Marketing ROI', 'World-class IMC treats measurement as a learning system, not a final report. This unit builds fluency in campaign metrics, dashboards, experiments, attribution, and ROI judgment.', 13),
  ('419a69f4-49fe-48d5-8e1f-5788d9f6b9a4', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'e4489dcd-df40-4195-9200-a06bc54f9445', 'subtopic'::public.curated_course_node_type, 'Measurement Planning', 'Students learn to define success before launch so every tactic has a measurement role.', 0),
  ('020853af-cc15-47c4-b0ec-b591f0ed214d', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '419a69f4-49fe-48d5-8e1f-5788d9f6b9a4', 'concept'::public.curated_course_node_type, 'Objectives, KPIs, targets, benchmarks, and decision rules', null, 0),
  ('839dffb6-c14e-475a-8c7f-26483d9909ae', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '419a69f4-49fe-48d5-8e1f-5788d9f6b9a4', 'concept'::public.curated_course_node_type, 'Input, output, outcome, and business-impact metrics', null, 1),
  ('0755e4d0-d907-4d91-af46-152029385310', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '419a69f4-49fe-48d5-8e1f-5788d9f6b9a4', 'concept'::public.curated_course_node_type, 'Measurement briefs, tagging plans, and dashboard design', null, 2),
  ('dbace122-1d80-4dfa-a4cc-8fa73fc85d19', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'e4489dcd-df40-4195-9200-a06bc54f9445', 'subtopic'::public.curated_course_node_type, 'Attribution and Incrementality', 'The point is to understand what can and cannot be claimed from campaign data.', 1),
  ('d630ba90-1d6d-4f55-9d84-48b20e317388', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'dbace122-1d80-4dfa-a4cc-8fa73fc85d19', 'concept'::public.curated_course_node_type, 'Last-click, multi-touch, marketing mix modeling, geo tests, holdouts, and lift studies', null, 0),
  ('26581fc9-cf35-47e5-9f77-16cbfb37308e', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'dbace122-1d80-4dfa-a4cc-8fa73fc85d19', 'concept'::public.curated_course_node_type, 'Correlation versus causation and common attribution bias', null, 1),
  ('33856856-deeb-42af-8d1f-dae51c11b3f7', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'dbace122-1d80-4dfa-a4cc-8fa73fc85d19', 'concept'::public.curated_course_node_type, 'Privacy changes, cookie loss, walled gardens, and modeled conversions', null, 2),
  ('f75579b5-ac33-4593-b4bc-195def4f8bf3', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'e4489dcd-df40-4195-9200-a06bc54f9445', 'subtopic'::public.curated_course_node_type, 'ROI and Learning Loops', 'Students learn how to interpret performance in a way that improves future strategy.', 2),
  ('74912103-a45e-4928-b6d4-87a0c8a51f2b', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'f75579b5-ac33-4593-b4bc-195def4f8bf3', 'concept'::public.curated_course_node_type, 'ROI, ROAS, CAC, LTV, payback, marginal return, and diminishing returns', null, 0),
  ('d089feb0-4997-42ae-bd7e-4826c34750cf', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'f75579b5-ac33-4593-b4bc-195def4f8bf3', 'concept'::public.curated_course_node_type, 'Creative, audience, offer, channel, and landing page diagnostics', null, 1),
  ('de397093-8f26-4dcc-a933-c4eae9b46f3a', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'f75579b5-ac33-4593-b4bc-195def4f8bf3', 'concept'::public.curated_course_node_type, 'Post-campaign analysis, recommendations, and knowledge management', null, 2),
  ('23ac4bc1-98bc-41aa-afab-cdcf2ae069d0', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'Budgeting, Forecasting and Resource Allocation', 'IMC decisions are constrained by budget, time, talent, and risk. This section teaches students how to allocate resources with financial discipline and strategic intent.', 14),
  ('549d4a3c-0b9f-4434-80c4-e6f5c2493902', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '23ac4bc1-98bc-41aa-afab-cdcf2ae069d0', 'subtopic'::public.curated_course_node_type, 'Budgeting Methods', 'Students learn common ways organizations set communication budgets and the trade-offs each creates.', 0),
  ('467128f9-a224-40f5-893a-51587f438dcf', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '549d4a3c-0b9f-4434-80c4-e6f5c2493902', 'concept'::public.curated_course_node_type, 'Objective-and-task, percentage-of-sales, competitive parity, affordability, and experimental budgets', null, 0),
  ('e1782f09-1c9c-4654-bd7c-e9071a4d6727', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '549d4a3c-0b9f-4434-80c4-e6f5c2493902', 'concept'::public.curated_course_node_type, 'Working versus non-working media costs', null, 1),
  ('28ae84b1-f52b-4d72-932b-9c6c641c5812', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '549d4a3c-0b9f-4434-80c4-e6f5c2493902', 'concept'::public.curated_course_node_type, 'Production, agency, technology, talent, research, and contingency costs', null, 2),
  ('bf58c301-069b-4960-ac72-2798debe3222', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '23ac4bc1-98bc-41aa-afab-cdcf2ae069d0', 'subtopic'::public.curated_course_node_type, 'Forecasting Campaign Results', 'The aim is to make campaign plans testable before money is committed.', 1),
  ('fff45461-5f8f-4f0e-84f4-70571506731f', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'bf58c301-069b-4960-ac72-2798debe3222', 'concept'::public.curated_course_node_type, 'Reach, response, conversion, revenue, margin, and lifetime value assumptions', null, 0),
  ('97aeced0-af60-490d-98a2-bced21c11613', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'bf58c301-069b-4960-ac72-2798debe3222', 'concept'::public.curated_course_node_type, 'Scenario planning and sensitivity analysis', null, 1),
  ('9781f85e-0c3f-49d7-b86d-826905ee62d5', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'bf58c301-069b-4960-ac72-2798debe3222', 'concept'::public.curated_course_node_type, 'Expected value and risk-adjusted campaign choices', null, 2),
  ('48f1c5d4-11b6-4eac-8614-03fe8e2df0b1', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '23ac4bc1-98bc-41aa-afab-cdcf2ae069d0', 'subtopic'::public.curated_course_node_type, 'Resource Allocation', 'Students learn to distribute spend across audiences, channels, creative, and time.', 2),
  ('a15712d4-cc8c-4ead-81d0-ff750fb16a14', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '48f1c5d4-11b6-4eac-8614-03fe8e2df0b1', 'concept'::public.curated_course_node_type, 'Portfolio balance between brand and performance', null, 0),
  ('d869f288-fe9d-4ad7-af3a-6bf4d18b6dbe', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '48f1c5d4-11b6-4eac-8614-03fe8e2df0b1', 'concept'::public.curated_course_node_type, 'Marginal return, saturation, and budget reallocation', null, 1),
  ('7714aa98-0ff7-43ed-89c5-3eec4b365275', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '48f1c5d4-11b6-4eac-8614-03fe8e2df0b1', 'concept'::public.curated_course_node_type, 'Governance for mid-campaign optimization', null, 2),
  ('c59d4550-9c57-4c9b-a5db-2faf57ef61e8', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'Legal, Ethical, Privacy and Inclusive Communication', 'IMC operates in a trust environment shaped by law, platform policy, data use, representation, and social responsibility. This section makes ethical judgment part of campaign quality.', 15),
  ('52112339-05f9-4f1e-9922-3d5c7a091675', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'c59d4550-9c57-4c9b-a5db-2faf57ef61e8', 'subtopic'::public.curated_course_node_type, 'Advertising Law and Claims', 'Students learn the basic guardrails for truthful, substantiated, and non-deceptive communication.', 0),
  ('25c4224f-b9f5-4f1b-a52e-c6ca8c8ff26d', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '52112339-05f9-4f1e-9922-3d5c7a091675', 'concept'::public.curated_course_node_type, 'Claim substantiation, comparative advertising, endorsements, disclosures, and native advertising', null, 0),
  ('d84507e0-88c2-432a-9f25-29871ca96127', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '52112339-05f9-4f1e-9922-3d5c7a091675', 'concept'::public.curated_course_node_type, 'FTC, platform policies, industry self-regulation, and brand review processes', null, 1),
  ('bd74a3bf-2ab0-4aed-b906-d4afd5be2333', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '52112339-05f9-4f1e-9922-3d5c7a091675', 'concept'::public.curated_course_node_type, 'Regulated categories and high-risk claims', null, 2);
