  ('94b8510e-0d05-48d5-85ca-0f2efb26c86c', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'c59d4550-9c57-4c9b-a5db-2faf57ef61e8', 'subtopic'::public.curated_course_node_type, 'Privacy and Responsible Personalization', 'The point is to use data in ways that preserve consent, dignity, and trust.', 1),
  ('26a49abb-2d72-466d-8736-1d1e37018923', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '94b8510e-0d05-48d5-85ca-0f2efb26c86c', 'concept'::public.curated_course_node_type, 'Consent, preference management, data minimization, security, and retention', null, 0),
