  ('7458b043-e890-442f-bc76-380438079dfa', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '565d39e7-9c7d-4383-926d-1e91f6b136b0', 'concept'::public.curated_course_node_type, 'Accessibility in copy, visuals, video, color, captions, and UX', null, 1),
  ('673dd665-d3c4-435f-aec0-e154cbc47aee', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '565d39e7-9c7d-4383-926d-1e91f6b136b0', 'concept'::public.curated_course_node_type, 'Sustainability, social claims, and avoiding purpose-washing', null, 2),
  ('651ec6ee-4915-4081-8a11-790c347292b5', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', null, 'topic'::public.curated_course_node_type, 'Campaign Operations, Agency Collaboration and Client Presentation', 'Excellent strategy must survive real execution. This unit teaches the workflow, collaboration, presentation, and decision skills that make IMC campaigns operationally credible.', 16),
  ('ed3e1d5a-7db5-4e01-b3dd-732181256ba8', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '651ec6ee-4915-4081-8a11-790c347292b5', 'subtopic'::public.curated_course_node_type, 'Campaign Workflow', 'Students learn how campaign work moves from brief to launch to optimization to post-analysis.', 0),
  ('198485c2-cf47-46d0-8050-ec7da781ad4a', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ed3e1d5a-7db5-4e01-b3dd-732181256ba8', 'concept'::public.curated_course_node_type, 'Schedules, milestones, status systems, review rounds, and launch checklists', null, 0),
  ('c5750d08-7ca8-4024-96e9-83f5166139f0', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ed3e1d5a-7db5-4e01-b3dd-732181256ba8', 'concept'::public.curated_course_node_type, 'Creative, media, PR, legal, analytics, sales, and product coordination', null, 1),
  ('b1079e9a-a6db-465b-b759-559f3b65e54b', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ed3e1d5a-7db5-4e01-b3dd-732181256ba8', 'concept'::public.curated_course_node_type, 'Asset trafficking, QA, naming conventions, and handoff discipline', null, 2),
  ('8dd9069a-f568-47f0-ae74-74915dce7762', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '651ec6ee-4915-4081-8a11-790c347292b5', 'subtopic'::public.curated_course_node_type, 'Agency and Vendor Collaboration', 'The focus is on working professionally with agencies, freelancers, media partners, and internal teams.', 1),
  ('01840645-0652-4d82-952d-0a654dbac313', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '8dd9069a-f568-47f0-ae74-74915dce7762', 'concept'::public.curated_course_node_type, 'Scopes of work, deliverables, roles, fees, timelines, and change management', null, 0),
