  ('307e3ce7-a8c6-49c4-b69d-64fdd9a9e36c', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '91475e3e-e52d-450f-a71d-a1e8084adcdb', 'concept'::public.curated_course_node_type, 'Narrative structure, strategic rationale, evidence, and trade-offs', null, 0),
  ('f6e5edbc-ca86-4807-afc3-1199a65d386b', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '91475e3e-e52d-450f-a71d-a1e8084adcdb', 'concept'::public.curated_course_node_type, 'Visualizing plans, budgets, journey maps, and dashboards', null, 1),
  ('52cfef63-941b-427e-b05e-08456db23832', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '91475e3e-e52d-450f-a71d-a1e8084adcdb', 'concept'::public.curated_course_node_type, 'Handling objections, defending assumptions, and documenting decisions', null, 2),
