  ('102178be-1e20-40fd-8f72-8aaaf288e308', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ddb82b2e-f6dd-48cf-8746-87a2b9cfc9bf', 'concept'::public.curated_course_node_type, 'Situation analysis, brand audit, customer insight, competitor review, and opportunity definition', null, 0),
  ('9c9f8038-6d0f-41ef-81c1-f0c8bfe06e95', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'ddb82b2e-f6dd-48cf-8746-87a2b9cfc9bf', 'concept'::public.curated_course_node_type, 'Campaign objective, target audience, positioning, and key message', null, 1),
