  ('d09ae7a0-4ae7-4e65-84cc-a72d6d483a81', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', 'bb2bb652-8d5a-450a-8b45-b70c0af23ca4', 'concept'::public.curated_course_node_type, 'Creative platform, message map, channel mix, media calendar, PR plan, content system, CRM flow, and activation plan', null, 0),
