  ('4c2acaaa-1de3-4ec2-86d3-24b88454990e', 'c4d5e6f7-8a9b-4c74-9d15-2e3f4a5b6c74', '1269c111-a7e1-49db-8c65-bd30a02e8758', 'subtopic'::public.curated_course_node_type, 'Pitch, Measurement and Reflection', 'Students finish by presenting the campaign and explaining how it will be evaluated and improved.', 2),
